        /**
        * Metodo que inicia el Administrador de Tareas, con la ventana oculta             
        */
        static void StartHiddenTaskManager()
        {
            Process p = new Process();
            p.StartInfo.WorkingDirectory = Environment.GetFolderPath(Environment.SpecialFolder.System);
            p.StartInfo.FileName = "taskmgr.exe";
            p.StartInfo.CreateNoWindow = true;
            p.StartInfo.WindowStyle = ProcessWindowStyle.Hidden;
            p.Start();
        }
        /**
        * Cierra el administrador de tareas
        */
        static void CloseTaskManager()
        {
            //Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Error, "MainWindow", "CloseTaskManager", "Ejecuta CloseTaskManager");

            //Process[] procs = Process.GetProcessesByName("taskmgr");
            //Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Error, "MainWindow", "CloseTaskManager", $"procs: {procs.Length}");

            //for (int i = 0; i < procs.Length; i++)
            //{
            //    try
            //    {
            //        procs[i].Kill();
            //    }
            //    catch
            //    {
            //    }
            //}

            Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindow", "CloseTaskManager", "Intentando cerrar el Administrador de Tareas.");

            try
            {
                Process[] taskManagerProcesses = Process.GetProcessesByName("taskmgr");
                Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindow", "CloseTaskManager", $"Se encontraron {taskManagerProcesses.Length} procesos de Administrador de Tareas.");

                foreach (Process process in taskManagerProcesses)
                {
                    try
                    {
                        process.Kill();
                        Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindow", "CloseTaskManager", "Se finalizó con éxito el proceso del Administrador de Tareas.");
                    }
                    catch (Win32Exception ex)
                    {
                        // Esta excepción ocurre si el proceso no se puede finalizar (ej. por permisos).
                        Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Error, "MainWindow", "CloseTaskManager",
                                                            $"No se pudo finalizar el proceso. Razón: {ex.Message}");
                    }
                    catch (InvalidOperationException)
                    {
                        // Esta excepción ocurre si el proceso ya se había cerrado.
                        Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Warn, "MainWindow", "CloseTaskManager",
                                                            "Se intentó finalizar un proceso del Administrador de Tareas que ya había salido.");
                    }
                }
            }
            catch (Exception ex)
            {
                // Captura cualquier otra excepción inesperada, como problemas al obtener los procesos.
                Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Error, "MainWindow", "CloseTaskManager",
                                                    $"Ocurrió un error inesperado: {ex.Message}");
            }


        }

        /**
           * Asegurar que el Task Manager siempre esta abierto y oculto.
           * Si esta cerrado, lo abre de nuevo. Si tiene focus, llama al 
           * metodo para quitarselo, ya que si tiene focus, aun que sea 
           * invisible cuando se presiona 'Supr' o 'Del', puede matar un proceso.
           */
        static void HideTaskManager()
        {
            // while (true)
            {
                try
                {
                    //Obtener la ventana del administrador de tareas
                    //(ingles y español)
                    int taskManager =
                        FindWindow("#32770", "Windows Task Manager");
                    int adminTareas =
                        FindWindow("#32770", "Administrador de tareas de Windows");

                    //Si no existe, crearlo
                    if (taskManager == 0 && adminTareas == 0)
                    {
                        StartHiddenTaskManager();
                    }
                }
                catch (Exception e)
                {
                    Console.WriteLine(e);
                }
            }
        }

