        void bloqueaEscritorioVirutal(bool bloquear)
        {
            try
            {
                // Ruta en el registro para bloquear la vista de tareas
                string registryPath = @"SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\Explorer";
                using (RegistryKey key = Registry.CurrentUser.CreateSubKey(registryPath))
                {
                    if (key != null)
                    {
                        // Valor que bloquea la creación de escritorios virtuales
                        key.SetValue("NoWinKeys", 1, RegistryValueKind.DWord);
                        Console.WriteLine("Escritorios virtuales bloqueados correctamente.");
                    }
                    else
                    {
                        Console.WriteLine("Error al acceder al registro.");
                    }
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine("Error: " + ex.Message);
            }


        }
