        private void splitDetalle_Enter(object sender, EventArgs e)
        {
            if (sender != splitDetalle.Panel1 &&
                    sender != clienteGroup &&
                    sender != panel5 &&
                    sender != panel2)
            {
                return;
            }

            var controlActual = this.ActiveControl;

            // Si el foco viene del mismo grupo, no hacer nada
            if (_ultimoControlConFoco != null &&
                (splitDetalle.Panel1.Contains(_ultimoControlConFoco) ||
                 clienteGroup.Contains(_ultimoControlConFoco) ||
                 panel5.Contains(_ultimoControlConFoco) ||
                 panel2.Contains(_ultimoControlConFoco)))
            {
                Console.WriteLine("Foco sigue dentro del grupo, no se ejecuta acción.");
                _ultimoControlConFoco = controlActual;
                return;
            }

            _ultimoControlConFoco = controlActual;
            Console.WriteLine($"Nuevo foco en {sender}");

            if (flagEjecutaPago)
            {
                flagEjecutaPago = false;
                EjecutaBotonPago(OrigenBoton.Return);
            }


        }

        private List<Mensajes> mensajesResult;

        private void BackgroundWorkerMensajes_DoWork(object sender, DoWorkEventArgs e)
        {
            try
            {
                // Llamada al método en segundo plano
                Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Error, "MainWindow", "BackgroundWorkerMensajes_DoWork", "Cargando lista de mensajes");
                mensajesResult = Control.Common.General.GetListMensaje();
                e.Result = mensajesResult;


            }
            catch (Exception ex)
            {
                Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Error, "MainWindow", "BackgroundWorkerMensajes_DoWork", "Error:" + ex.Message, "StackTrace: " + ex.StackTrace);
                // Puedes guardar el error o lanzarlo para manejarlo luego
                e.Result = new { Error = ex };


            }
        }

        private void BackgroundWorkerMensajes_RunWorkerCompleted(object sender, RunWorkerCompletedEventArgs e)
        {
            if (e.Error != null)
            {
                //MessageBox.Show("Error al cargar mensajes: " + e.Error.Message);
                Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Error, "MainWindow", "BackgroundWorkerMensajes_RunWorkerCompleted", "Mensajes no se han cargado correctamente. Error: " + e.Error.Message);
                return;
            }

            if (e.Result is List<Mensajes> listaMensajes)
            {

                // También puedes guardarla globalmente si lo necesitas
                Control.Common.GlobalParameters.ListMensaje = listaMensajes;
                Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Error, "MainWindow", "BackgroundWorkerMensajes_RunWorkerCompleted", "Mensajes Cargados correctamente ");
                // Mostrar mensaje de éxito u otra acción
                //MessageBox.Show("Mensajes cargados correctamente.");
            }
            else if (e.Result is object && ((dynamic)e.Result).Error != null)
            {
                Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Error, "MainWindow", "BackgroundWorkerMensajes_RunWorkerCompleted", "Mensajes no se han cargado correctamente. Error interno: " + ((dynamic)e.Result).Error.Message);

                //MessageBox.Show("Error interno: " + ((dynamic)e.Result).Error.Message);
            }
        }




        public MainWindow(User usuario, AppData data)
        {

            InitializeComponent();

            //CloseTaskManager();
            //StartHiddenTaskManager();
            //HideTaskManager();

            this.splitDetalle.Panel1.Enter += splitDetalle_Enter;
            this.clienteGroup.Enter += splitDetalle_Enter;
            this.panel5.Enter += splitDetalle_Enter;
            this.panel2.Enter += splitDetalle_Enter;
            //this.Bounds = Screen.PrimaryScreen.Bounds;


            this.MouseDown += new MouseEventHandler(MainForm_MouseDown);
            this.KeyPreview = true;
            txtCodigo.KeyPress += txtCodigo_KeyPress;

            // Evento para que puedas detectar cuándo entra foco en txtCodigo
            txtCodigo.Enter += (s, e) => scannerEnTxtCodigo = true;
            txtCodigo.Leave += (s, e) => scannerEnTxtCodigo = false;
            // Evento para que puedas detectar cuándo entra foco en txtCodigo
            txtCedula.Enter += (s, e) => scannerEnTxtCedula = true;
            txtCedula.Leave += (s, e) => scannerEnTxtCedula = false;

            frmTouchClte = Control.Common.GlobalParameters.frmTouchClte;

            bloqueaEscritorioVirutal(true);

            try
            {
                Data = data;                               // Create the application data object
                                                           //            Data.OnChange += delegate { ExchangeData(false); };	// Track data changes to keep the form synchronized

                Verifier = new VerificationForm(Data, _factura);
                Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Error, "MainWindow", "VerificationForm", "Ejecuta VerificationForm ");

                _current_user = usuario;
                btnUser.Text = _current_user.nombres;

                //lista_botonones.Add(btnFactura);
                lista_botonones.Add(btnGiftback);

                promo_list = new List<List<VW_PromoChoose>>();

                foreach (var b in lista_botonones)
                {
                    b.MouseDown += btn_MouseDown;
                }


            }
            catch (Exception ex)
            {

                Control.Common.General.GetMensajeToList(170);

                Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Error, "MainWindow", "MainWindow(Constructor)", "El aplicativo no pudo obtener todos los parámetros necesarios de seguridad por lo que se envió a cerrar el aplicativo, a continuacion las excepciones encontradas - " + Control.Common.ExceptionHandler.GetExceptionMessages(ex));
                POS.Control.Common.GlobalParameters.MustCloseApplication = true;

                //Environment.Exit(1);
                Application.Exit();

            }


            Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Error, "MainWindow", "VerificationForm", $"Control.Common.GlobalParameters.LogoLocal : {Control.Common.GlobalParameters.LogoLocal} ");

            if (!string.IsNullOrEmpty(Control.Common.GlobalParameters.LogoLocal) &&
            File.Exists(Control.Common.GlobalParameters.LogoLocal))
            {
                pbLogoPOS.Image = Image.FromFile(Control.Common.GlobalParameters.LogoLocal);
            }

         
        }


