        private void agregaProductosTmp(string codigo)
        {
            Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Error, "MainWindow", "agregaProductosTmp", "Ejecuta agregaProductosTmp ");

            List<ParametrosMensajes> parametros = new List<ParametrosMensajes>();

            if (NoGrabaTMP == "FALSE" && !Es2X_CONSULTA_POS)
            {
                // Ruta compartida por local.  JM 11-09-2019 
                string nombre_BD = Application.StartupPath + "\\Libs\\POS.db";

                string conexion = "Data Source=" + nombre_BD + ";Version=3;";

                SQLiteConnection sq = new System.Data.SQLite.SQLiteConnection(conexion);

                string comando = "BEGIN TRANSACTION;delete from detalle;INSERT INTO detalle(item_id,cantidad,unidades,subtotal,descuento,iva,total,unidad,costo,precio) VALUES ";
                try
                {

                    sq.Open();
                    //inicio de transaccion y borrado de datos anteriores
                    SQLiteCommand cmd;
                    //Codigo para insertar las nuevas lineas
                    string datos = "";
                    foreach (Producto prod in _factura.Productos)
                    {
                        datos = datos + "('" + prod.Id + "'," + prod.Cantidad + "," + prod.Unidades + "," + prod.Subtotal + "," + prod.Descuento + "," + prod.Iva + "," + prod.Total + ",'" + prod.Unidad + "'," + prod.Costo + "," + prod.Pvp + "), ";
                    }
                    if (_factura.Productos.Count > 0)
                    {
                        comando = comando + datos.Substring(0, datos.Length - 2) + ";COMMIT; ";
                    }
                    else
                    {
                        comando = "BEGIN TRANSACTION;delete from detalle; COMMIT;";
                    }
                    cmd = new SQLiteCommand(comando, sq);
                    cmd.ExecuteNonQuery();
                    cmd.Dispose();
                    cmd = null;


                    // MessageBox.Show(this,retorno.ToString());

                }
                catch (Exception ex)
                {
                    string MsjError = string.Concat(comando, "; ", ex.Message);
                    Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Error, "MainWindow", "AgregaProductoTmp"
                        , "No fue posible agregar productos a la factura temporal, a continuacion las excepciones encontradas - "
                        + Control.Common.ExceptionHandler.GetExceptionMessages(ex), "StackTrace: "
                        + ex.StackTrace);


                    //Manejo de error
                    //System.Windows.Forms.MessageBox.Show(this, comando);
                    //System.Windows.Forms.MessageBox.Show(this, ex.Message);

                    //msgBoxCtrl.ShowMessage(MsgBoxCtrl.MessageType.Error, MsjError, "POS");
                    //Control.Common.General.GetMensaje("POS", MsjError, "I");

                    parametros = new List<ParametrosMensajes>();
                    parametros.Add(new ParametrosMensajes() { codigo = "[MsjError]", valor = codigo });
                    Control.Common.General.GetMensajeToList(586, parametros);


                }

                //Cerramos conexion

                sq.Close();
                sq.Dispose();
                sq = null;
            }

        }

        private void txtCedula_KeyPress(object sender, KeyPressEventArgs e)
        {
            //CloseTaskManager();

            if (e.KeyChar == (char)Keys.Delete || e.KeyChar == (char)Keys.Back)
            {
                codigoBarraBuffer = string.Empty;  // también limpia el buffer si borran
                buffer.Clear();
                txtCedula.Text = "";
            }


            if (txtCedula.Text.Length != txtCedula.SelectionStart)
            {
                e.Handled = true;
            }

            if (txtCedula.Text.Trim().StartsWith(POS.Control.Common.GlobalParameters.AppMovil_PrefijoUsaApp))
            {
                LimpiarClienteCompraGratis();
                tempo666.Start();
            }


            //if (!char.IsControl(e.KeyChar) && !char.IsDigit(e.KeyChar) && (e.KeyChar != '-')
            //            && (e.KeyChar != '\'' && (e.KeyChar != '\'')
            //            )
            //{
            //    B09262482121712202445&_
            //        e.Handled = true;
            //}

            if (InputLanguage.CurrentInputLanguage.Culture.EnglishName.ToUpper() != "ENGLISH (UNITED STATES)")
            {
                foreach (InputLanguage lang in InputLanguage.InstalledInputLanguages)
                {
                    if (lang.Culture.EnglishName.ToUpper() == "ENGLISH (UNITED STATES)")
                    {
                        InputLanguage.CurrentInputLanguage = lang;
                    }
                }
            }

            bool confirmaCambioClteDevIVA = false;
            if (e.KeyChar == (char)Keys.Enter)
            {

                string itendifacionCompleta = txtCedula.Text;

                if (cliente_actual != null && cliente_actual.ACCOUNTNUM != null)
                {
                    if (!cliente_actual.ACCOUNTNUM.Equals(itendifacionCompleta) && !cliente_actual.VATNUM.Equals(itendifacionCompleta))
                    {
                        if (Control.Common.GlobalParameters.SRI_DEVOLUCION_IVA)
                        {
                            if (_factura.esBeneficiarioDevolucionIVA && _factura.aplicaBeneficioDevolucionIVA)
                            {
                                if (_factura.montoIvaDevolver != 0)
                                {
                                    //661
                                    var resultado2 = Control.Common.General.GetMensajeToList(661); // Confirmación para aplicar IVA

                                    if (resultado2 == MsgBoxCtrl.MessageBoxResult.Ok || resultado2 == MsgBoxCtrl.MessageBoxResult.Yes)
                                    {
                                        var reverso = ejecutaReversoDevolucionIVA();
                                        _factura.aplicaBeneficioDevolucionIVA = false;
                                        _factura.montoIvaDevolver = 0;

                                        HabilitaControlesFormaPago("FORMAPAGO_GENERAL");
                                        confirmaCambioClteDevIVA = true;
                                    }

                                }

                                //if (!confirmaCambioClteDevIVA) { return; }
                            }



                        }

                        Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Error, "MainWindow", "txtCedula_KeyPress"
                        , $"Genera mensaje de validación ");
                        var result = Control.Common.General.GetMensajeToList(56);

                        if (result == MsgBoxCtrl.MessageBoxResult.Ok || result == MsgBoxCtrl.MessageBoxResult.Yes)
                        {
                            validaClienteSp(itendifacionCompleta);

                            if (cliente_actual.ACCOUNTNUM != GlobalclteEmpleado.Identificacion)
                            {
                                itendifacionCompleta = string.Empty;

                                _factura.EsUsoAppMovil = false;
                                txtCedula.Text = cliente_actual.ACCOUNTNUM;
                                txtCedula.Focus();
                            }
                        }
                        else
                        {
                            var pos = new POSEntities();
                            if (pos.core_parametro.Where(x => x.identificador == "SWITCH_COSTUMER" && x.parametro2 == establecimiento_inicio).First().valor == "TRUE")
                            {
                                if (pos.core_parametro.Where(x => x.identificador == "FINGERPRINT" && x.parametro2 == establecimiento_inicio).First().valor == "TRUE")
                                {
                                    Verifier = new VerificationForm(Data, _factura);
                                    Verifier.Tag = "adm";
                                    verificador = Verifier.ShowDialog();
                                    //  MessageBox.Show(this,Verifier.Tag.ToString());
                                    if (verificador == DialogResult.OK)
                                    {
                                        _factura.Productos.Clear();
                                        lblEtiquetaSaldo.Visible = false;
                                        lblSaldoTarjeta.Visible = false;

                                        if (_factura.Descuentos2.Any())
                                        {
                                            _factura.Descuentos2.Clear();
                                            _factura.Pagos.Clear();
                                        }

                                        calcularFactura();
                                        insertaCabeceraFile();  //insertaCabecera();

                                        itendifacionCompleta = string.Empty;

                                        _factura.EsUsoAppMovil = false;
                                        txtCedula.Text = cliente_actual.ACCOUNTNUM;
                                        txtCedula.Focus();

                                    }
                                    return;
                                }
                                try
                                {
                                    DialogResult _authorize;
                                    _inputFormAuthUser.setValue(String.Empty);
                                    _inputFormAuthUser._txtInput.PasswordChar = '•';
                                    _authorize = _inputFormAuthUser.ShowDialog();
                                    focused = (System.Windows.Forms.Control)_inputFormAuthUser._txtInput;
                                }
                                catch (Exception ex)
                                {
                                    Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindow", "cambiarCliene", "Error:" + ex.Message);

                                    Control.Common.General.GetMensajeToList(231);

                                    //MessageBox.Show(this, "Por favor, intente nuevamente", "Advertencia Cambia Cliente", MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
                                }


                                if (focused.Text.ToString() != "")
                                {
                                    Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindow", "txtCedula_KeyPress", "focused");


                                    if (ValidateAuthorizationUser(focused.Text.ToString()) == true)
                                    {
                                        Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindow", "txtCedula_KeyPress", "ValidateAuthorizationUser es TRUE ");
                                        Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindow", "txtCedula_KeyPress", "borra items de la factura  ");
                                        _factura.Productos.Clear();
                                        lblEtiquetaSaldo.Visible = false;
                                        lblSaldoTarjeta.Visible = false;

                                        if (_factura.Descuentos2.Any())
                                        {
                                            _factura.Descuentos2.Clear();
                                            _factura.Pagos.Clear();
                                        }

                                        calcularFactura();
                                        insertaCabeceraFile();  //insertaCabecera();
                                    }

                                }
                            }

                            itendifacionCompleta = string.Empty;

                            _factura.EsUsoAppMovil = false;
                            _factura.EsClienteApp = false;
                            _factura.CodigoClienteApp = "";
                            _factura.codigoclienteAPP = "";

                            txtCedula.Text = cliente_actual.ACCOUNTNUM;
                            txtCedula.Focus();
                            return;
                        }
                    }
                }
                else
                {
                    validaClienteSp(itendifacionCompleta);
                }

                frmTouchClte = Control.Common.GlobalParameters.frmTouchClte;
                if (Control.Common.GlobalParameters.PANTALLA_CLIENTE && frmTouchClte != null && !frmTouchClte.IsDisposed)
                {
                    frmTouchClte.ActualizarDatosCliente(GlobalclteEmpleado);
                }


            }

        }


        private void validaClienteSp(string itendifacionCompleta)
        {
            string identificacion = txtCedula.Text.Trim();
            string EstablecimientoAxCode = Control.Common.GlobalParameters.EstablecimientoAxCode;
            string identificacionAnt = string.Empty;
            Screen targetScreenCajero = Control.Common.General.GetScreenCajero();
            Screen targetScreenClte = Control.Common.General.GetScreenClte();

            try
            {
                if (string.IsNullOrEmpty(itendifacionCompleta))
                {

                    Control.Common.General.GetMensajeToList(632);
                    return;

                }

                Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindow", "validaClienteSp", "Ejecuta metodo ValidaClienteEmpleado. Identificación: " + txtCedula.Text + " | EstablecimientoAxCode: " + Control.Common.GlobalParameters.EstablecimientoAxCode);
                ClienteEmpleado clteEmpleado = Control.Common.General.ValidaClienteEmpleado(itendifacionCompleta, EstablecimientoAxCode);
                /*custclassificationgroup custClass = Control.Common.General.ValidaClienteEmpresarial(itendifacionCompleta);
                */
                Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindow", "validaClienteSp", $"Ejecuta metodo ValidaClienteEmpleado. clteEmpleado.CodMensaje: {clteEmpleado.CodMensaje}" +
                    $"; clteEmpleado.TextMensaje {clteEmpleado.TextMensaje}; " +
                    $"clteEmpleado.CodError {clteEmpleado.CodError}; " +
                    $"clteEmpleado.MsjError {clteEmpleado.MsjError}; "
                    );

                /*Si encuentro cliente valido salta este registro*/
                if (clteEmpleado.CodMensaje != "0")
                {
                    if (clteEmpleado.EsClienteDuplicado)
                    {
                        Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindow", "validaClienteSp", "Cliente duplicado, se envia correo ");

                        string cedula = clteEmpleado.Identificacion;

                        try
                        {
                            if (!string.IsNullOrWhiteSpace(Control.Common.GlobalParameters.IpMaquina))
                            {
                                var xmlRespuesta = Control.Common.Mail.EnviaCorreo(
                                    Properties.Settings.Default.MAILERROR_FROM,
                                    Properties.Settings.Default.MAILERROR_ALIAS,
                                    Properties.Settings.Default.MAILERROR_DESTINO,
                                    Properties.Settings.Default.MAILERROR_CC,
                                    "POS Cliente duplicado",
                                    String.Format("El cliente con identificacion " + cedula + " tiene registros duplicados en pos_customer sea por su campo AccountNum o VatNum, esto no afecta a la facturacion y normal funcionamiento de POS, pero deberia ser regularizado  \n\nEstablecimiento: {0} \nPto Emision: {1} \nIpMaquina: {2} \nCajeroNombre: {3} \nCajeroIdentificacion: {4}",
                                                Control.Common.GlobalParameters.Establecimiento,
                                                Control.Common.GlobalParameters.PuntoEmision,
                                                Control.Common.GlobalParameters.IpMaquina,
                                                Control.Common.GlobalParameters.UsuarioNombre,
                                                Control.Common.GlobalParameters.Usuario),
                                    false,
                                    String.Empty);

                                if (!xmlRespuesta.DocumentElement.GetAttribute("CodError").Equals("0"))
                                {
                                    Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Error, "Cliente", "validaClienteSp", "No se pudo enviar notificacion de cliente duplicado, a continuacion las excepciones encontradas - " + xmlRespuesta.DocumentElement.GetAttribute("MsgError"));
                                }

                                Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Error, "Cliente", "validaClienteSp", "El cliente con identificacion " + cedula + " tiene registros duplicados en pos_customer sea por su campo AccountNum o VatNum, esto no afecta a la facturacion y normal funcionamiento de POS, pero deberia ser regularizado");
                            }
                        }
                        catch (Exception ex)
                        {
                            Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindow", "validaClienteSp", $"Error al enviar correo, Cliente Duplicado: {ex.Message} ");

                        }
                    }

                    int CodMensaje = Int32.Parse(clteEmpleado.CodMensaje);

                    if (CodMensaje != 0)
                    {
                        switch (CodMensaje)
                        {
                            case 18:
                                var result = Control.Common.General.GetMensajeToList(CodMensaje);

                                if (result == MsgBoxCtrl.MessageBoxResult.Yes || result == MsgBoxCtrl.MessageBoxResult.Ok)
                                {
                           
                                    var fClte = new POS.Control.Clientes.ClienteForm();
                                    fClte._cliente = null;

                                    fClte.DeseaPermitirCambioBasico = true;

                                    fClte.identificacion = clteEmpleado.Identificacion; //txtCedula.Text;
                                    fClte.ShowDialog();

                                    if (fClte._cliente != null)
                                    {
                                        cliente_actual = fClte._cliente;
                                        txtCedula.Text = cliente_actual.VATNUM;
                                        setClienteData();
                                        txtCodigo.Focus();
                                        txtCodigo.SelectAll();

                                        //Levantar encuesta
                                        POS.Control.Encuestas.EncuestaHandler.LevantarEncuestaFactura();
                                        //VALIDACION DESCUENTOS / OSCAR POZO
                                        cambiarCliente(clteEmpleado.Identificacion);
                                        _factura.EsClienteApp = clteEmpleado.EsClienteApp;
                                        _factura.codigoclienteAPP = clteEmpleado.CodigoClienteApp;
                                        insertaCabeceraFile(clteEmpleado);  //insertaCabecera();
                                        //Mostrar mensajes para cliente
                                        var InvoiceMessagePrompter = new POS.Control.Main.ClsFacturaMensaje();
                                        InvoiceMessagePrompter.ShowInvoiceMessages(cliente_actual.ACCOUNTNUM);

                                    }

                                }
                                else
                                {

                                    if (cliente_actual == null)
                                        txtCedula.Clear();
                                    else
                                        txtCedula.Text = cliente_actual.ACCOUNTNUM;

                                }
                                break;

                            case 25:
                                Control.Common.General.GetMensajeToList(CodMensaje);
                                txtCedula.Clear();
                                break;

                            default:

                                Control.Common.General.GetMensajeToList(CodMensaje);
                                txtCedula.Text = string.Empty;
                                clteEmpleado.Identificacion = string.Empty;
                                txtCedula.Clear();
                                break;
                        }
