        private void validaCliente(string itendifacionCompleta)
        {
            ClienteEmpleado clteEmpleado = new ClienteEmpleado();

            try
            {
                if (txtCedula.Text.Trim().StartsWith(POS.Control.Common.GlobalParameters.AppMovil_PrefijoUsaApp))
                {

                    clteEmpleado = Control.Common.General.ValidaClienteEmpleado(txtCedula.Text.Trim(), Control.Common.GlobalParameters.EstablecimientoAxCode);

                    if (clteEmpleado != null)
                    {
                        Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindow", "txtCedula_KeyPress", "CodError: " + clteEmpleado.CodError + ", MsjError: " + clteEmpleado.MsjError);

                        codigoclienteAPP = clteEmpleado.CodigoClienteApp;
                        txtCedula.Text = clteEmpleado.Identificacion;
                        _factura.EsUsoAppMovil = true;
                        _factura.EsClienteApp = true;

                    }
                    else
                    {
                        Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindow", "txtCedula_KeyPress", "ValidaClienteEmpleado no encontro datos o no encontro el proceso. Se recuperan datos manuales ");


                        if (txtCedula.Text.Trim().IndexOf("-") > 0)
                        {
                            codigoclienteAPP = txtCedula.Text.Trim().Substring(txtCedula.Text.Trim().IndexOf("-") + 1, (txtCedula.Text.Trim().Length - txtCedula.Text.Trim().IndexOf("-")) - 1);
                            txtCedula.Text = txtCedula.Text.Trim().Substring(0, txtCedula.Text.Trim().IndexOf("-"));
                            _factura.EsUsoAppMovil = true;
                        }
                    }

                    lblIdClienteApp.Text = codigoclienteAPP;
                    Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindow", "txtCedula_KeyPress", "CodError: " + clteEmpleado.CodError + ", MsjError: " + clteEmpleado.MsjError);


                    ClienteCompraGratis = txtCedula.Text.Trim();

                    if (POS.Control.Common.GlobalParameters.CompraGratis)
                    {
                        VerificarSaldoCompraGratis();
                    }

                    //txtCedula.Text = txtCedula.Text.Trim().Remove(0, POS.Control.Common.GlobalParameters.AppMovil_PrefijoUsaApp.Length);
                    _factura.EsUsoAppMovil = true;

                    usotarjetadscto = false;
                    var val1 = txtCedula.Text.Trim();
                    if (val1.Length > 0)
                    {
                        // Validar si tiene puntos acumulados para activar boton pagar con monedero.
                        ValidarMonederoCampania(txtCedula.Text);
                    }

                }

                usotarjetadscto = false;
                var val = txtCedula.Text.Trim();
                codigocliente = val;
                if (val.Length > 0)
                {
                    cambiarCliente(val);
                }

                // Llamar a Parqueo.  JM 08-03-2019
                if (Control.Common.GlobalParameters.Parking_TienePermiso)
                {
                    SolicitarParqueo();
                }
            }
            catch (Exception ex)
            {
                Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindow", "txtCedula_KeyPress", "ValidaClienteEmpleado - error: " + ex.Message);
            }
        }

        private void cambiarClienteAnt(string val)
        {
            List<ParametrosMensajes> parametros = new List<ParametrosMensajes>();
            var pos = new POSEntities();

            if (cliente_actual != null && cliente_actual.ACCOUNTNUM != null)
            {
                if (!cliente_actual.ACCOUNTNUM.Equals(val) && !cliente_actual.VATNUM.Equals(val))
                {
                    Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "Control/Clientes", "cambiarCliente", $"Valido si el objecto cliente_actual tiene datos");
                    var result = Control.Common.General.GetMensajeToList(56);
                    if (result == MsgBoxCtrl.MessageBoxResult.Ok || result == MsgBoxCtrl.MessageBoxResult.Yes)
                    {
                        _factura.EsUsoAppMovil = false;
                        return;
                    }


                    lblEtiquetaSaldo.Visible = false;
                    lblSaldoTarjeta.Visible = false;

                    if (_factura.Descuentos2.Any())
                    {
                        _factura.Descuentos2.Clear();
                        _factura.Pagos.Clear();
                    }

                    //Valida: al cambiar el cliente se borre el pago con billetera electrónica
                    Pago pagoBElect = null;
                    foreach (var pago in _factura.Pagos)
                    {
                        if (pago.Descripcion == "DINE ELECT")
                        {
                            pagoBElect = pago;
                        }
                    }
                    if (pagoBElect != null)
                    {
                        _factura.Pagos.Remove(pagoBElect);
                    }

                    //Valida: al cambiar el cliente se borre el pedido app
                    if (_factura.EsPedidoOtraApp == true)
                    {
                        _factura.EsPedidoOtraApp = false;
                        _factura.PedidoOtraApp.Pedido = string.Empty;
                        _factura.PedidoOtraApp.Tipo = (byte)CANALVENTA.VENTANORMALPOS;
                        lblCanalVenta.Text = "Venta POS";


                        _factura.Productos.Clear();
                        lblEtiquetaSaldo.Visible = false;
                        lblSaldoTarjeta.Visible = false;

                        lblPedidoOtrasApp.Text = string.Empty;
                        lblPedidoOtrasApp.Visible = false;
                    }

                    //calcularFactura();
                    insertaCabeceraFile();  //insertaCabecera();
                }
                else
                {
                    Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "Control/Clientes", "cambiarCliente", $"cliente_actual.ACCOUNTNUM: {val}");
                    Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "Control/Clientes", "cambiarCliente", $"cliente_actual.VATNUM: {val}");

                    if (pos.core_parametro.Where(x => x.identificador == "SWITCH_COSTUMER" && x.parametro2 == establecimiento_inicio).First().valor == "TRUE")
                    {
                        if (pos.core_parametro.Where(x => x.identificador == "FINGERPRINT" && x.parametro2 == establecimiento_inicio).First().valor == "TRUE")
                        {
                            Verifier = new VerificationForm(Data, _factura);
                            Verifier.Tag = "adm";
                            verificador = Verifier.ShowDialog();
                            //  MessageBox.Show(this,Verifier.Tag.ToString());
                            if (verificador == DialogResult.OK)
                            {
                                _factura.Productos.Clear();
                                lblEtiquetaSaldo.Visible = false;
                                lblSaldoTarjeta.Visible = false;

                                if (_factura.Descuentos2.Any())
                                {
                                    _factura.Descuentos2.Clear();
                                    _factura.Pagos.Clear();
                                }

                                calcularFactura();
                                insertaCabeceraFile();  //insertaCabecera();
                            }
                            return;
                        }
                        try
                        {
                            DialogResult _authorize;
                            _inputFormAuthUser.setValue(String.Empty);
                            _inputFormAuthUser._txtInput.PasswordChar = '•';
                            _authorize = _inputFormAuthUser.ShowDialog();
                            focused = (System.Windows.Forms.Control)_inputFormAuthUser._txtInput;
                        }
                        catch (Exception ex)
                        {
                            Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "Control/Clientes", "cambiarCliente", "Error: " + ex.Message);
                            Control.Common.General.GetMensajeToList(231);
                            //MessageBox.Show(this, "Por favor, intente nuevamente", "Advertencia Cambia Cliente", MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
                        }

                        if (focused.Text.ToString() != "")
                        {
                            if (ValidateAuthorizationUser(focused.Text.ToString()) == true)
                            {
                                _factura.Productos.Clear();
                                lblEtiquetaSaldo.Visible = false;
                                lblSaldoTarjeta.Visible = false;

                                if (_factura.Descuentos2.Any())
                                {
                                    _factura.Descuentos2.Clear();
                                    _factura.Pagos.Clear();
                                }

                                calcularFactura();
                                insertaCabeceraFile();  //insertaCabecera();
                            }
                            else
                            {
                                Control.Common.General.GetMensajeToList(624);
                                //MessageBox.Show(this, "Código no válido ó Usuario no autorizado. Intente nuevamente", "Código de Autorización", MessageBoxButtons.OK, MessageBoxIcon.Hand);
                                return;
                            }
                        }
                    }

                }
            }


            if (Cliente.clienteExiste(val))
            {
                if (val == "9999999999999")
                {
                    parametros = new List<ParametrosMensajes>();
                    parametros.Add(new ParametrosMensajes() { codigo = "[PARAMETRO_CF]", valor = Control.Common.GlobalParameters.CUPO_CF.ToString() });
                    Control.Common.General.GetMensajeToList(57, parametros);

                }

                core_tarjetacreditointerno tarjeta = null;
                core_tarjetacreditointerno tarjetaAdicional = null;
                var nuevo_cliente = Cliente.getCliente(val, out tarjeta, out tarjetaAdicional);

                if (tarjeta != null)
                {
                    _factura.TarjetaCreditoInterno = tarjeta;
                    _factura.TarjetaCreditoInternoAdicional = tarjetaAdicional;

                    lblEtiquetaSaldo.Visible = true;
                    lblSaldoTarjeta.Visible = true;
                    lblSaldoTarjeta.Text = string.Format("{0:C}", (tarjetaAdicional == null) ? tarjeta.saldo : tarjetaAdicional.saldo);

                }
                if (nuevo_cliente != null)
                {
                    if (nuevo_cliente.EMAIL == "")
                    {
                        var result = Control.Common.General.GetMensajeToList(58);
                        if (result == MsgBoxCtrl.MessageBoxResult.Ok || result == MsgBoxCtrl.MessageBoxResult.Yes)
                        {
                            var f = new POS.Control.Clientes.ClienteForm();
                            f._cliente = nuevo_cliente;
                            f.ShowDialog();
                            if (f._cliente != null)
                            {
                                cliente_actual = f._cliente;
                                txtCedula.Text = cliente_actual.VATNUM;
                                txtCodigo.Focus();
                                txtCodigo.SelectAll();
                                nuevo_cliente = f._cliente;
                            }
                        }
                    }

                    cliente_actual = nuevo_cliente;
                }

                if (cliente_actual != null)
                {
                    setClienteData();
                    txtCodigo.Focus();
                    txtCodigo.SelectAll();
                    insertaCabeceraFile();  //insertaCabecera();
                }
                else
                {
                    clearClienteData();
                    txtCedula.Text = "";
                    txtCedula.Focus();
                }

                if (clienteActivo())
                {
                    CambiarCliente_RecalcularFactura();
                    //actualizarDatos(nuevo_cliente);

                    //Levantar encuesta
                    POS.Control.Encuestas.EncuestaHandler.LevantarEncuestaFactura();

                    //Mostrar mensajes para cliente
                    var InvoiceMessagePrompter = new POS.Control.Main.ClsFacturaMensaje();
                    InvoiceMessagePrompter.ShowInvoiceMessages(cliente_actual.ACCOUNTNUM);
                }


            }
            else
            {
                if (ValidarIdentificador.ValidarCedula(val)
                       || ValidarIdentificador.ValidarRUCPrivada(val)
                       || ValidarIdentificador.ValidarRUCPublica(val)
                       || ValidarIdentificador.ValidarRUCNatural(val))
                {
                    var result = Control.Common.General.GetMensajeToList(59);
                    if (result == MsgBoxCtrl.MessageBoxResult.Ok || result == MsgBoxCtrl.MessageBoxResult.Yes)
                    {
                        var objCliente = new POS.Control.Clientes.ClienteForm();
                        objCliente._cliente = null;
                        objCliente.identificacion = val; //txtCedula.Text;
                        objCliente.ShowDialog();

                        if (objCliente._cliente != null)
                        {
                            cliente_actual = objCliente._cliente;
                            txtCedula.Text = cliente_actual.VATNUM;
                            setClienteData();
                            insertaCabeceraFile();  //insertaCabecera();
                            txtCodigo.Focus();
                            txtCodigo.SelectAll();

                            //Levantar encuesta
                            POS.Control.Encuestas.EncuestaHandler.LevantarEncuestaFactura();

                            //Mostrar mensajes para cliente
                            var InvoiceMessagePrompter = new POS.Control.Main.ClsFacturaMensaje();
                            InvoiceMessagePrompter.ShowInvoiceMessages(cliente_actual.ACCOUNTNUM);
                        }
                        else
                        {
                            if (cliente_actual == null)
                                txtCedula.Clear();
                            else
                                txtCedula.Text = cliente_actual.ACCOUNTNUM;
                        }
                    }
                    else
                    {
                        if (cliente_actual == null)
                            txtCedula.Clear();
                        else
                            txtCedula.Text = cliente_actual.ACCOUNTNUM;
                    }
                }
                else
                {
                    //MessageBoxTemporal.Show("Cedula o RUC no Valido!\nSi es Pasaporte Ingreselo en AX ", "Mensaje", 30, true);
                    //MessageBox.Show(this, "Cedula o RUC no Valido!\nSi es Pasaporte Ingreselo en AX ", "Mensaje");
                    Control.Common.General.GetMensajeToList(60);
                    txtCedula.Clear();
                }
            }
            if (cliente_actual != null)
            {
                verificarPromocionEspanola(cliente_actual.ACCOUNTNUM);
            }

        }
        private void cambiarCliente(string val, ClienteEmpleado clteEmpleado = null)
        {
            List<ParametrosMensajes> parametros = new List<ParametrosMensajes>();
            var pos = new POSEntities();

            if (cliente_actual != null && cliente_actual.ACCOUNTNUM != null)
            {
                _factura.EsTarjetaCreditoInterno = false;
                _factura.EsTarjetaCreditoInternoAdicional = false;
                _factura.NumeroTarjetaEmpresa = string.Empty;
                _factura.NumeroTarjetaEmpresaAdicional = string.Empty;
                _factura.TarjetaCreditoInterno = new core_tarjetacreditointerno();
                _factura.TarjetaCreditoInternoAdicional = new core_tarjetacreditointerno();
                _factura.EsClienteApp = false;
                _factura.CodigoClienteApp = "";
                _factura.codigoclienteAPP = "";


                if (_factura.Descuentos2.Any())
                {
                    _factura.Descuentos2.Clear();
                    _factura.Pagos.Clear();
                }


                if (_factura.Pagos.Any())
                {
                    _factura.Pagos.Clear();
                }

                //Valida: al cambiar el cliente se borre el pago con billetera electrónica
                Pago pagoBElect = null;
                foreach (var pago in _factura.Pagos)
                {
                    if (pago.Descripcion == "DINE ELECT")
                    {
                        pagoBElect = pago;
                    }
                }
                if (pagoBElect != null)
                {
                    _factura.Pagos.Remove(pagoBElect);
                }

                //Valida: al cambiar el cliente se borre el pedido app
                if (_factura.EsPedidoOtraApp == true)
                {
                    Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindow", "cambiarCliente", $"_factura.EsPedidoOtraApp : {_factura.EsPedidoOtraApp }");

                    _factura.EsPedidoOtraApp = false;
                    _factura.PedidoOtraApp.Pedido = string.Empty;
                    _factura.PedidoOtraApp.Tipo = (byte)CANALVENTA.VENTANORMALPOS;
                    lblCanalVenta.Text = "Venta POS";

                    Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindow", "cambiarCliente", $"limpia productos");
                    _factura.Productos.Clear();
                    lblEtiquetaSaldo.Visible = false;
                    lblSaldoTarjeta.Visible = false;

                    lblPedidoOtrasApp.Text = string.Empty;
                    lblPedidoOtrasApp.Visible = false;

                }

                insertaCabeceraFile();  //insertaCabecera();

                if (Control.Common.GlobalParameters.SRI_DEVOLUCION_IVA)
                {
                    if (_factura.aplicaBeneficioDevolucionIVA && _factura.montoIvaDevolver != 0)
                    {

                        datosDocumnetos datosDocumentos = new datosDocumnetos();
                        datosDocumentos.tipoDocumnto = "F";
                        datosDocumentos.tipoComprobante = "04";
                        datosDocumentos.numSecuencia = _factura.Secuencia;
                        datosDocumentos.ruc_matriz = _factura.Ruc_matriz;
                        datosDocumentos.claveAccesoComprobante = _factura.ClaveAccesoSRI;
                        datosDocumentos.identificacion = _factura.ClienteIdentificacion;
                        datosDocumentos.baseImponible = _factura.GetBase12();
                        datosDocumentos.montoIva = _factura.getIVA();
                        datosDocumentos.montoIvaDevolver = _factura.getIVA();

                        var respuestaAnulaDevolucion = EjecutaAnulaDevolucionIVA(datosDocumentos);
                        if (respuestaAnulaDevolucion.codigo == "6007")
                        {

                            string Mensaje = $"Se realiza el Reverso de la Devolución de IVA " +
                                $"\n por {respuestaAnulaDevolucion.montoIvaDevolver:N} \n de la factura";


                            respuestaAnulaDevolucion.mensaje = Mensaje;

                            imprimeTicketDevolcionIVA(
                                respuestaAnulaDevolucion.codigo,
                                respuestaAnulaDevolucion.mensaje,
                                _factura.ClienteIdentificacion,
                                _factura.Cliente_nombre,
                                "REVERSA_IVA");

                            parametros.Add(new ParametrosMensajes() { codigo = "[PARAMETRO_CF]", valor = Control.Common.GlobalParameters.CUPO_CF.ToString() });
                            Control.Common.General.GetMensajeToList(57);

                            _factura.aplicaBeneficioDevolucionIVA = false;
                            _factura.montoIvaDevolver = 0;
                            _factura.pinClteDevolucion = "";


                            DevolucionIvaModel devolucionIva = new DevolucionIvaModel();
                            devolucionIva.tipoDocumento = _factura.Documento;
                            devolucionIva.establecimiento = _factura.Establecimiento;
                            devolucionIva.puntoEmision = _factura.PtoEmision;
                            devolucionIva.numDocumento = _factura.Secuencia.ToString();
                            devolucionIva.ClaveAccesoSRI = _factura.ClaveAccesoSRI;
                            devolucionIva.cliente = _factura.ClienteIdentificacion;
                            devolucionIva.montoIvaDevolver = _factura.montoIvaDevolver;
                            devolucionIva.estado = "R";

                            Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindow", "ejecutaReversoDevolucionIVA", $"Ejecuta metodo  grabaDevolucionIVA");
                            _factura.grabaDevolucionIVA(devolucionIva);

                            Control.Common.GlobalParameters.SRI_PIN_CLTE = string.Empty;

                            HabilitaControlesFormaPago("FORMAPAGO_GENERAL");

                            _factura.Documento = "F";

                            string ClaveAccesoSRI = string.Empty;
                            //crea clave de acceso sri
                            //var paramCl = pos.core_parametro.Where(x => x.identificador.Equals("ACTIVAR_CLAVE_ACCESO")
                            //                            &&
                            //                            (x.parametro2 == "TRUE" && x.valor.Contains(Control.Common.GlobalParameters.Establecimiento + ";")))
                            //                     .FirstOrDefault();
                            //if (paramCl != null)
                            //{
                            //    ClaveAccesoSRI = _factura.generarClaveAccesoSRI(_factura.Documento);
                            //}

                            _factura.ClaveAccesoSRI = _factura.generarClaveAccesoSRI(_factura.Documento);

                            Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindows", "getProducto", " reverso de IVA realizado correctamente. ");
                            Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindows", "getProducto", " variables fueron enceradas");
                        }
                        else
                        {
                            Control.Common.General.GetMensajeToList(656);
                            return;
                        }
                    }
                }


            }


            if (clteEmpleado == null || string.IsNullOrEmpty(clteEmpleado.Identificacion))
            {
                clteEmpleado = new ClienteEmpleado();
                clteEmpleado.Identificacion = val;

                clteEmpleado.EsTarjetaEmpresa = false;
                clteEmpleado.tarjeta = new core_tarjetacreditointerno();
                clteEmpleado.NumeroTarjetaEmpresa = string.Empty;

                clteEmpleado.EsTarjetaEmpresaAdicional = false;
                clteEmpleado.tarjetaAdicional = new core_tarjetacreditointerno();
                clteEmpleado.NumeroTarjetaEmpresaAdicional = string.Empty;
                clteEmpleado.esBeneficiarioDevolucionIVA = false;
            }

            // _factura.esBeneficiarioDevolucionIVA
            if (Cliente.clienteExiste(clteEmpleado.Identificacion))
            {
                Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindow", "cambiarCliente", $"Cliente.clienteExiste({val})");
                if (clteEmpleado.Identificacion == "9999999999999")
                {

                    GlobalclteEmpleado = clteEmpleado;
                    HabilitaControlesFormaPago("FORMAPAGO_GENERAL");

                    parametros = new List<ParametrosMensajes>();
                    parametros.Add(new ParametrosMensajes() { codigo = "[PARAMETRO_CF]", valor = Control.Common.GlobalParameters.CUPO_CF.ToString() });
                    parametros.Add(new ParametrosMensajes() { codigo = "[parámetro_CF]", valor = Control.Common.GlobalParameters.CUPO_CF.ToString() });

                    //this.BeginInvoke((MethodInvoker)delegate
                    //{
                    //    Control.Common.General.GetMensajeToList(57, parametros);
                    //});

                    Control.Common.General.GetMensajeToList(57, parametros);

                }

                var nuevo_cliente = Cliente.getCliente(clteEmpleado.Identificacion, _factura);

                if (nuevo_cliente != null && nuevo_cliente.ACCOUNTNUM != "9999999999999")
                {
                    if (nuevo_cliente.EMAIL == "")
                    {
                        var result = Control.Common.General.GetMensajeToList(58);
                        if (result == MsgBoxCtrl.MessageBoxResult.Ok || result == MsgBoxCtrl.MessageBoxResult.Yes)
                        {
                            var objCustomerEdit = new POS.Control.Clientes.ClienteForm();
                            objCustomerEdit._cliente = nuevo_cliente;
                            objCustomerEdit.DeseaPermitirCambioBasico = true;

                            objCustomerEdit.ShowDialog();
                            if (objCustomerEdit._cliente != null)
                            {
                                cliente_actual = objCustomerEdit._cliente;
                                txtCedula.Text = cliente_actual.VATNUM;
                                txtCodigo.Focus();
                                txtCodigo.SelectAll();
                                nuevo_cliente = objCustomerEdit._cliente;
                            }
                        }
                    }
                }


                cliente_actual = nuevo_cliente;
                if (cliente_actual != null)
                {

                    setClienteData();
                    txtCodigo.Focus();
                    txtCodigo.SelectAll();
                    _factura.EsClienteApp = clteEmpleado.EsClienteApp;
                    _factura.CodigoClienteApp = clteEmpleado.CodigoClienteApp;
                    //insertaCabeceraFile();  //insertaCabecera();
                    insertaCabeceraFile(clteEmpleado);
                }
                else
                {
                    clearClienteData();
                    txtCedula.Text = "";
                    txtCedula.Focus();
                }

                if (clienteActivo())
                {
                    CambiarCliente_RecalcularFactura();
                    //actualizarDatos(nuevo_cliente);

                    //Levantar encuesta
                    POS.Control.Encuestas.EncuestaHandler.LevantarEncuestaFactura();

                    //Mostrar mensajes para cliente
                    var ptosClte = Control.Common.General.GetMensajePtosClientes(cliente_actual.ACCOUNTNUM);
                    if (!string.IsNullOrEmpty(ptosClte.descripcion))
                    {
                        Control.Common.General.GetMensajeToList(ptosClte.id);
                    }

                    ////Mostrar mensajes para cliente
                    //var InvoiceMessagePrompter = new POS.Control.Main.ClsFacturaMensaje();
                    //InvoiceMessagePrompter.ShowInvoiceMessages(cliente_actual.ACCOUNTNUM);
                }
            }
            else
            {
                if (ValidarIdentificador.ValidarCedula(val)
                       || ValidarIdentificador.ValidarRUCPrivada(val)
                       || ValidarIdentificador.ValidarRUCPublica(val)
                       || ValidarIdentificador.ValidarRUCNatural(val))
                {
                    var result = Control.Common.General.GetMensajeToList(59);
                    if (result == MsgBoxCtrl.MessageBoxResult.Ok || result == MsgBoxCtrl.MessageBoxResult.Yes)
                    {
                        var objCliente = new POS.Control.Clientes.ClienteForm();
                        objCliente._cliente = null;
                        objCliente.identificacion = val; //txtCedula.Text;
                        objCliente.ShowDialog();

                        if (objCliente._cliente != null)
                        {
                            cliente_actual = objCliente._cliente;
                            txtCedula.Text = cliente_actual.VATNUM;
                            setClienteData();
                            _factura.EsClienteApp = clteEmpleado.EsClienteApp;
                            _factura.CodigoClienteApp = clteEmpleado.CodigoClienteApp;
                            insertaCabeceraFile();  //insertaCabecera();
                            txtCodigo.Focus();
                            txtCodigo.SelectAll();

                            //Levantar encuesta
                            POS.Control.Encuestas.EncuestaHandler.LevantarEncuestaFactura();


                            //Mostrar mensajes para cliente
                            var ptosClte = Control.Common.General.GetMensajePtosClientes(cliente_actual.ACCOUNTNUM);
                            if (!string.IsNullOrEmpty(ptosClte.descripcion))
                            {
                                Control.Common.General.GetMensajeToList(ptosClte.id);
                            }


                            //var InvoiceMessagePrompter = new POS.Control.Main.ClsFacturaMensaje();
                            //InvoiceMessagePrompter.ShowInvoiceMessages(cliente_actual.ACCOUNTNUM);
                        }
                        else
                        {
                            if (cliente_actual == null)
                                txtCedula.Clear();
                            else
                                txtCedula.Text = cliente_actual.ACCOUNTNUM;
                        }
                    }
                    else
                    {
                        if (cliente_actual == null)
                            txtCedula.Clear();
                        else
                            txtCedula.Text = cliente_actual.ACCOUNTNUM;
                    }
                }
                else
                {
                    //MessageBoxTemporal.Show("Cedula o RUC no Valido!\nSi es Pasaporte Ingreselo en AX ", "Mensaje", 30, true);
                    //MessageBox.Show(this, "Cedula o RUC no Valido!\nSi es Pasaporte Ingreselo en AX ", "Mensaje");
                    Control.Common.General.GetMensajeToList(60);
                    txtCedula.Clear();
                }
            }

            if (cliente_actual != null)
            {
                verificarPromocionEspanola(cliente_actual.ACCOUNTNUM);

            }


            frmTouchClte = Control.Common.GlobalParameters.frmTouchClte;
            if (Control.Common.GlobalParameters.PANTALLA_CLIENTE && frmTouchClte != null && !frmTouchClte.IsDisposed)
            {
                frmTouchClte.ActualizarDatosCliente(GlobalclteEmpleado);
            }

        }



        private void actualizarDatos(pos_customer cliente = null)
        {
            var c = cliente != null ? cliente : cliente_actual;
            _factura.updateItems(c);
        }

        private void clearClienteData()
        {
            cliente_actual = null;
            lblNombre.Text = "";
            lblDireccion.Text = "";
            lblTelefono.Text = "";
            txtCedula.Clear();
            txtCedula.Focus();
            lblEtiquetaSaldo.Visible = false;
            lblSaldoTarjeta.Visible = false;

            frmTouchClte = Control.Common.GlobalParameters.frmTouchClte;
            if (Control.Common.GlobalParameters.PANTALLA_CLIENTE && frmTouchClte != null && !frmTouchClte.IsDisposed)
            {

                frmTouchClte.ActualizarDatosCliente(null);
            }
        }

