                        if (db.core_parametro.Any(x => x.identificador == "BLOQUEOBOTONESFACTAPP" && x.parametro2 == this.FacturaActual.PedidoOtraApp.Tipo.ToString() && x.valor.ToUpper().Equals("TRUE")))
