                            queryServDomici = (from c in db1.core_facturaAPP
                                               join p in db1.core_facturadetalleAPP on c.id equals p.factura_id
                                               where c.orderApp == NumeroPedidoDelPortal
                                               && p.item_id.StartsWith("SERV")
                                               select p
