                Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindow", "CargarMainWindow", "INgreso setTituloDocumento");
                setTituloDocumento();

                Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindow", "CargarMainWindow", "INgreso enlazarControles");
