        void CargaParametrosPantallaClte()
        {
            try
            {
                using (var db = new POSEntities())
                {
                    string estabPtEmiEsperado = _factura?.Establecimiento + _factura?.PtoEmision;

                    if (string.IsNullOrEmpty(estabPtEmiEsperado))
                    {
                        Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Warn,
                            "frmNotificacionApertura", "CargaParametrosPantallaClte",
                            "Establecimiento o PtoEmisión no definidos.");
                        return;
                    }


                    // Paso 1: Obtener candidatos desde BD (sin Split ni operaciones no compatibles)
                    var candidatos = db.core_parametro
                        .Where(p => p.identificador == "PANTALLA_CLIENTE" && p.valor == "TRUE" && p.documento != null)
                        .ToList(); // Traemos a memoria
                                   // Paso 2: Filtrar en memoria usando Split()

                    var parametroPantallaCliente = candidatos
                        .FirstOrDefault(p =>
                        {
                            try
                            {
                                string[] partes = p.documento.Split(new[] { '|' });
                                return partes.Length >= 2 && partes[1] == estabPtEmiEsperado;
                            }
                            catch
                            {
                                return false;
                            }
                        });


                    Control.Common.GlobalParameters.PANTALLA_CLIENTE = false;


                    if (parametroPantallaCliente == null)
                    {
                        Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info,
                            "frmNotificacionApertura", "CargaParametrosPantallaClte",
                            "No se encontró configuración válida para PANTALLA_CLIENTE.");
                        return;
                    }

                    // Activamos la funcionalidad
                    Control.Common.GlobalParameters.PANTALLA_CLIENTE = true;

                    string[] documento = parametroPantallaCliente.documento.Split('|');
                    string deviceName = documento[0];

                    int targetWidth = 1024;
                    int targetHeight = 768;

                    if (parametroPantallaCliente.parametro2 != null)
                    {
                        string[] dimensiones = parametroPantallaCliente.parametro2.Split('|');
                        if (dimensiones.Length >= 2 &&
                            int.TryParse(dimensiones[0], out int parsedWidth) &&
                            int.TryParse(dimensiones[1], out int parsedHeight))
                        {
                            targetWidth = parsedWidth;
                            targetHeight = parsedHeight;
                        }
                    }

                    // Guardar en parámetros globales
                    Control.Common.GlobalParameters.DeviceName = deviceName;
                    Control.Common.GlobalParameters.targetWidth = targetWidth;
                    Control.Common.GlobalParameters.targetHeight = targetHeight;

                    // Log info
                    Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info,
                        "frmNotificacionApertura", "CargaParametrosPantallaClte",
                        $"DeviceName: {deviceName}, Ancho: {targetWidth}, Alto: {targetHeight}");
                }
            }
            catch (Exception ex)
            {
                Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Error,
                    "frmNotificacionApertura", "CargaParametrosPantallaClte",
                    $"Error al cargar parámetros de pantalla cliente: {ex.Message}");
            }
        }


