        private bool AplicarDescuentoCuponV2(string codigoCupon)
        {
            bool respuesta = false;

            int tienePago = _factura.Pagos.Count;
            bool EsUsoCuponPromocional = _factura.EsUsoCuponPromocional;

            string sQuery = string.Empty;
            var pos = new POSEntities();
            DataSet dtsConsulta = new DataSet();
            string CadenaConexion = pos.Database.Connection.ConnectionString;
            DataTable tblVoucher = new DataTable();
            SqlConnection con = new SqlConnection();

            if (string.IsNullOrEmpty(codigoCupon))
            {
                respuesta = false;
                return respuesta;
            }

            DataTable ArticuloPOS = UDT_DetArticuloPOS.GetDataTableArticuloPOS();
            DataTable DetDescuentos = UDT_DetDescuentos.GetDataTableDetDescuentos();

            var db = new POSEntities();
            var cupon = db.core_TarjetaDescuento.Where(x => x.codigo == codigoCupon && x.numeroFactura == -1).FirstOrDefault();


            if (_factura.Productos.Count() > 0)
            {
                foreach (var producto in _factura.Productos)
                {

                    DataRow workRow = ArticuloPOS.NewRow();
                    workRow["OrigenConsulta"] = "";
                    workRow["ITEMID"] = producto.Id;
                    workRow["CANTIDAD"] = producto.Cantidad;
                    ArticuloPOS.Rows.Add(workRow);

                    if (producto.DescuentosCupon == null)
                    {
                        producto.DescuentosCupon = new List<Descuento>();
                    }
                    else
                    {

                        foreach (var detDscto in producto.DescuentosCupon)
                        {
                            DataRow workRowDsct = DetDescuentos.NewRow();
                            workRowDsct["establecimiento"] = "";
                            workRowDsct["punto_emision"] = "";
                            workRowDsct["tipo_descuento"] = "";
                            workRowDsct["codigo"] = detDscto.codigo;
                            workRowDsct["parametro"] = detDscto.parametro;
                            workRowDsct["parametro2"] = detDscto.parametro2;
                            workRowDsct["valor"] = detDscto.valor;
                        }

                    }
                }


            }

            try
            {
                using (con = new SqlConnection(CadenaConexion))
                {
                    con.Open();
                    int usuCuponPromociona = EsUsoCuponPromocional == false ? 0 : 1;


                    sQuery = string.Empty;
                    sQuery = string.Concat(sQuery, $"Declare @CodError int  ", Environment.NewLine);
                    sQuery = string.Concat(sQuery, $"Declare @MsjError varchar(254) ", Environment.NewLine);
                    sQuery = string.Concat(sQuery, $"Declare @RespAplicaDsto varchar(254) ", Environment.NewLine);
                    sQuery = string.Concat(sQuery, $" Exec spPOSAplicarDescuentoCupon ", Environment.NewLine);
                    sQuery = string.Concat(sQuery, $"  @codigoCupon = '{codigoCupon}'", Environment.NewLine);
                    sQuery = string.Concat(sQuery, $"  ,@TblDetalleArticulosVta ", Environment.NewLine);
                    sQuery = string.Concat(sQuery, $"  ,@TblDetCuponDescuento ", Environment.NewLine);
                    sQuery = string.Concat(sQuery, $"  ,@EsUsoCuponPromocional = {usuCuponPromociona}", Environment.NewLine);
                    sQuery = string.Concat(sQuery, $"  ,@TienePagos = {tienePago}", Environment.NewLine);
                    sQuery = string.Concat(sQuery, $"  ,@CodError , @MsjError, @RespAplicaDsto", Environment.NewLine);


                    using (SqlCommand cmd = new SqlCommand(sQuery, con))
                    {
                        var objArticulo = new SqlParameter("@TblDetalleArticulosVta", SqlDbType.Structured);
                        objArticulo.TypeName = "dbo.UDT_DetArticuloPOS";
                        objArticulo.Value = ArticuloPOS;
                        cmd.Parameters.Add(objArticulo);

                        var DetCuponDescuento = new SqlParameter("@TblDetCuponDescuento", SqlDbType.Structured);
                        DetCuponDescuento.TypeName = "dbo.UDT_CuponDescuento";
                        DetCuponDescuento.Value = DetDescuentos;
                        cmd.Parameters.Add(DetCuponDescuento);
                    }

                }
            }
            catch (Exception)
            {

                throw;
            }

            respuesta = true;

            return respuesta;

        }

        private bool AplicarDescuentoCupon(string codigoCupon, ref bool encontroCupon)
        {
            encontroCupon = false; // 🔴 IMPORTANTE: Inicializar siempre
            bool respuesta = false;

            Control.Common.Logger.LogMessage(
                Control.Common.Enum.LogTypes.Info,
                "MainWindow",
                "AplicarDescuentoCupon",
                $"Inicia método con cupón: {codigoCupon}");

            try
            {
                // Eliminar caracteres inválidos (siempre limpiar entrada)
                codigoCupon = codigoCupon.Replace("A", "").Trim();

                using (POSEntities db = new POSEntities())
                {
                    // 1. Buscar cupón en BD
                    var cupon = db.core_TarjetaDescuento
                        .Where(x => x.codigo == codigoCupon && x.numeroFactura == -1)
                        .FirstOrDefault();


                    if(cupon == null)
                    {
                        Control.Common.Logger.LogMessage(
                                 Control.Common.Enum.LogTypes.Info,
                                 "MainWindows",
                                 "AplicarDescuentoCupon",
                                 " cupon es NULL ");

                        return false;
                    }

                    if (!cupon.activo)
                    {
                        Control.Common.General.GetMensajeToList(146);
                        //msgBoxCtrl.ShowMessage(MsgBoxCtrl.MessageType.Error, "Cupón ya fue utilizado en otra facturar", "POS - Cupón Promocional");
                        //System.Windows.Forms.MessageBox.Show(this, "Cupón ya fue utilizado en otra factura", "Cupón Promocional", MessageBoxButtons.OK, MessageBoxIcon.Stop);
                        return false;
                    }

           

                    // 2. Validar que no haya pagos cargados
                    if (_factura.Pagos.Count > 0)
                    {
                        Control.Common.General.GetMensajeToList(55);
                        return false;
                    }

                    // 3. Obtener descuentos asociados al cupón
                    var itemsCupon = db.core_descuento
                        .Where(x => x.tipo_descuento == "ProductoCantidadCupon"
                                 && x.parametro2 == cupon.codigo
                                 && x.activo)
                        .ToList();

                    // 4. Determinar tipo de cupón: general o por producto
                    bool esCuponGeneral = !itemsCupon.Any();
                     decimal porcDescuento = cupon.saldo / 100M; // Convertir saldo % a decimal (ej: 1500 → 15%)

                    if (porcDescuento < 0 || porcDescuento > 100)
                    {
                        Control.Common.General.GetMensajeToList(145); // Porcentaje inválido
                        return false;
                    }

                    // 5. Verificar si ya se aplicó este cupón en esta factura (evitar duplicado)
                    if (_factura.EsUsoCuponPromocional && _factura.CuponPromocionalCodigo == cupon.codigo)
                    {
                        Control.Common.General.GetMensajeToList(131); // Cupón ya aplicado en esta factura
                        return false;
                    }

                    // 6. Procesar descuentos por producto
                    bool algunProductoAplicado = false;

                    foreach (var producto in _factura.Productos.ToList()) // .ToList() para evitar modificación durante iteración
                    {
                       

                        // Buscar si este producto tiene un descuento específico en core_descuento
                        var itemCuponProducto = itemsCupon.FirstOrDefault(x => x.parametro == producto.Id.ToString());

                        if (itemCuponProducto != null)
                        {
                            // ✅ Caso 1: Descuento específico para este producto

                            // Validar que no se haya aplicado ya este cupón a este producto
                            if (producto.DescuentosCupon != null &&
                                producto.DescuentosCupon.Any(d => d.codigo == cupon.codigo))
                            {
                                Control.Common.General.GetMensajeToList(131); // Ya aplicado
                                continue; // Saltar este producto, no fallar toda la factura
                            }


                            // Calcular valor del descuento
                            decimal valorDsctoTotal = 0;
                            //valorDsctoUnaUnidad = (producto.SubtotalSinDescuento / producto.Unidades) * porcDescuento;
                            valorDsctoTotal = (producto.Pvp * porcDescuento); 
                            //valorDsctoUnaUnidad = producto.Pvp * producto.Cantidad * porcDescuento;


                            // Crear nuevo descuento
                            var descuento = new Descuento
                            {
                                codigo = cupon.codigo,
                                parametro = porcDescuento.ToString(),
                                valor = itemCuponProducto.valor // Guardar original (puede ser -1 o valor fijo)
                            };

                            if (producto.DescuentosCupon == null)
                                producto.DescuentosCupon = new List<Descuento>();

                            producto.DescuentosCupon.Add(descuento);
                            producto.DescuentoAX += valorDsctoTotal;

                            producto.update(false);

                            algunProductoAplicado = true;
                        }
                    }

                    // 7. Si no hay productos específicos, aplicar descuento general a TODOS los productos
                    if (esCuponGeneral && !_factura.Productos.All(p => p.DescuentosCupon?.Any(d => d.codigo == cupon.codigo) == true))
                    {
                        foreach (var producto in _factura.Productos)
                        {
                            // Evitar aplicar si ya se le aplicó este cupón por otro motivo
                            if (producto.DescuentosCupon != null &&
                                producto.DescuentosCupon.Any(d => d.codigo == cupon.codigo))
                                continue;

                            decimal valorDscto = producto.SubtotalSinDescuento * porcDescuento;
                            producto.DescuentoAX = valorDscto;
                            producto.Descuentos.Clear(); // Limpia descuentos antiguos si existen
                            producto.Descuento = 0;
                            producto.update(false);

                            algunProductoAplicado = true;
                        }
                    }

                    // 8. Si al menos un producto recibió el descuento, registrar el cupón en la factura
                    if (algunProductoAplicado)
                    {
                        _factura.EsUsoCuponPromocional = true;
                        _factura.CuponPromocionalPorcDesc = porcDescuento;
                        _factura.CuponPromocionalCodigo = cupon.codigo;
                        
                        Control.Common.Logger.LogMessage(
                            Control.Common.Enum.LogTypes.Info,
                            "MainWindow",
                            "AplicarDescuentoCupon",
                            $"Cupón '{cupon.codigo}' aplicado exitosamente en la factura.");

                        // Mensaje de éxito
                        var parametros = new List<ParametrosMensajes>
                        {
                            new ParametrosMensajes { codigo = "[CODIGO_CUPON]", valor = cupon.codigo }
                        };
                        Control.Common.General.GetMensajeToList(148, parametros);

                        calcularFactura(); // Recalcular totales
                        encontroCupon = true;
                        respuesta = true;
                    }
                    else
                    {
                        // Ningún producto fue afectado (quizás todos ya tenían el cupón)
                        Control.Common.General.GetMensajeToList(149); // No se aplicó
                    }
                }
            }
            catch (Exception ex)
            {
                Control.Common.Logger.LogMessage(
                    Control.Common.Enum.LogTypes.Error,
                    "MainWindow",
                    "AplicarDescuentoCupon",
                    $"Error aplicando cupón '{codigoCupon}': {Control.Common.ExceptionHandler.GetExceptionMessages(ex)}");

                respuesta = false;
            }

            return respuesta;
        }

