        private bool IntentarAplicarCupon(string codigo)
        {
            // 1. Validación inicial de entrada
            if (string.IsNullOrWhiteSpace(codigo))
            {
                Control.Common.Logger.LogMessage(
                    Control.Common.Enum.LogTypes.Warn,
                    "MainWindows",
                    "IntentarAplicarCupon",
                    "Código de cupón vacío o nulo recibido");
                return false; // No es un cupón válido
            }



            bool encontroCupon = false;
            bool aplicadoExitosamente = AplicarDescuentoCupon(codigo, ref encontroCupon);

            // 3. Loguear el resultado final con claridad
            if (aplicadoExitosamente)
            {
                Control.Common.Logger.LogMessage(
                    Control.Common.Enum.LogTypes.Info,
                    "MainWindows",
                    "IntentarAplicarCupon",
                    $"Cupón '{codigo}' aplicado exitosamente.");
            }
            else
            {
                Control.Common.Logger.LogMessage(
                    Control.Common.Enum.LogTypes.Info,
                    "MainWindows",
                    "IntentarAplicarCupon",
                    $"Cupón '{codigo}' NO pudo ser aplicado (inválido, inactivo, ya usado o conflicto).");
            }

            // 4. Retornar el resultado real: ¿Se aplicó o no?
            return aplicadoExitosamente;
        }

