        private void EjecutaConsultaCodigoItem(string codigo, object sender)
        {
            // 1. Validar cliente activo
            if (!clienteActivo())
            {
                Control.Common.General.GetMensajeToList(663);
                txtCedula.Focus();
                txtCedula.SelectAll();
                return;
            }

            // 2. Validar código
            if (string.IsNullOrWhiteSpace(codigo))
            {
                Control.Common.Logger.LogMessage(
                    Control.Common.Enum.LogTypes.Warn,
                    "MainWindows",
                    "EjecutaConsultaCodigoItem",
                    "Código vacío o nulo recibido");
                return;
            }

            Control.Common.Logger.LogMessage(
                Control.Common.Enum.LogTypes.Info,
                "MainWindows",
                "EjecutaConsultaCodigoItem",
                $"Iniciando consulta para código: {codigo}");

            try
            {

                Control.Common.Logger.LogMessage(
                        Control.Common.Enum.LogTypes.Info,
                        "MainWindows",
                        "EjecutaConsultaCodigoItem",
                        "IntentarAplicarCupon");

                var cuponAplicado = IntentarAplicarCupon(codigo);
                
                // 3. Intentar aplicar cupón
                if (cuponAplicado)
                {
                    Control.Common.Logger.LogMessage(
                        Control.Common.Enum.LogTypes.Info,
                        "MainWindows",
                        "EjecutaConsultaCodigoItem",
                        "Cupón procesado (aplicado o inválido)");
                    return;
                }

                Control.Common.Logger.LogMessage(
                        Control.Common.Enum.LogTypes.Info,
                        "MainWindows",
                        "EjecutaConsultaCodigoItem",
                        $"_factura.Documento: {_factura.Documento}");

                // 4. Asegurar tipo de documento
                if (string.IsNullOrEmpty(_factura.Documento))
                {
                    _factura.Documento = "F";
                    Control.Common.Logger.LogMessage(
                        Control.Common.Enum.LogTypes.Info,
                        "MainWindows",
                        "EjecutaConsultaCodigoItem",
                        "Documento no definido. Asignado tipo: F (Factura)");
                }

                // 5. Procesar producto o gift card
                if (_factura.Documento == "F")
                {
                    Control.Common.Logger.LogMessage(
                        Control.Common.Enum.LogTypes.Info,
                        "MainWindows",
                        "EjecutaConsultaCodigoItem",
                        $"Buscando producto con código: {codigo}");

                    getProducto(codigo);

                    Control.Common.Logger.LogMessage(
                        Control.Common.Enum.LogTypes.Info,
                        "MainWindows",
                        "EjecutaConsultaCodigoItem",
                        "Producto procesado exitosamente");
                }
                else
                {
                    Control.Common.Logger.LogMessage(
                        Control.Common.Enum.LogTypes.Info,
                        "MainWindows",
                        "EjecutaConsultaCodigoItem",
                        $"Buscando Gift Card con código: {codigo}");

                    getGiftCard(codigo);
                }

                // 6. Guardar en archivo temporal SOLO si fue procesado (implícito en getProducto/getGiftCard)
                GuardarEstadoTemporal(codigo);
            }
            catch (Exception ex)
            {
                Control.Common.Logger.LogMessage(
                    Control.Common.Enum.LogTypes.Error,
                    "MainWindows",
                    "EjecutaConsultaCodigoItem",
                    $"Error al procesar código '{codigo}': {ex.Message}\nStackTrace: {ex.StackTrace}");

                // Opcional: mostrar alerta amigable
                // MessageBox.Show("No se pudo procesar el artículo. Revise conexión o código.", "Error", MessageBoxButtons.OK, MessageBoxIcon.Warning);
            }
            finally
            {
                // 7. Limpiar y enfocar siempre
                txtCodigo.Clear();
                txtCodigo.Focus();
            }
        }

