                txtCedula.Focus();
                txtCedula.SelectAll();
            }
        }



        private void txtCodigo_KeyPress(object sender, KeyPressEventArgs e)
        {
            // Evitar edición en medio del texto
            if (txtCodigo.Text.Length != txtCodigo.SelectionStart)
            {
                e.Handled = true;
            }

            // 1. Solo procesar Enter
            if (e.KeyChar != (char)Keys.Enter)
                return;

            string codigo = txtCodigo.Text.Trim();

            // 2. Validar longitud mínima
            if (codigo.Length < Control.Common.GlobalParameters.MIN_CARACTER_CODIGO_ART)
            {
                e.Handled = true;
                return;
            }

            // 3. Evitar reentrada
            if (_isProcessing)
            {
                e.Handled = true;
                return;
            }

            _isProcessing = true;

            try
            {
               

                // Caso 1: App móvil
                if (codigo.StartsWith(POS.Control.Common.GlobalParameters.AppMovil_PrefijoUsaApp))
                {
                    LimpiarClienteCompraGratis();
                    tempo666.Start();
                    txtCedula.Text = codigo;
                    txtCodigo.Clear();
                    txtCedula_KeyPress(sender, e);
                    return;
                }

                // Caso 2: Cédula con '%'
                if (codigo.StartsWith("%"))
                {
                    txtCedula.Text = codigo;
                    txtCodigo.Clear();
                    txtCedula.Focus();
                    txtCedula_KeyPress(txtCedula, new KeyPressEventArgs((char)13));
                    e.Handled = true;
                    return;
                }

                // Caso 3: Artículo normal
                EjecutaConsultaCodigoItem(codigo, sender);
            }
            catch (Exception ex)
            {
                Control.Common.Logger.LogMessage(
                    Control.Common.Enum.LogTypes.Error,
                    "MainWindows", "txtCodigo_KeyPress",
                    $"Error procesando código: {ex.Message}\nStack: {ex.StackTrace}");
            }
            finally
            {
                _isProcessing = false;
            }

            e.Handled = true;
            txtCodigo.Focus(); // Por si acaso
        }



