        private System.Windows.Forms.Control GetFocusedControl(System.Windows.Forms.Control container)
        {
            foreach (System.Windows.Forms.Control ctrl in container.Controls)
            {
                if (ctrl.Focused)
                {
                    return ctrl;
                }

                if (ctrl.HasChildren)
                {
                    System.Windows.Forms.Control found = GetFocusedControl(ctrl);
                    if (found != null)
                        return found;
                }
            }

            return null;
        }


        private bool EsCampoEditable(System.Windows.Forms.Control control)
        {
            return control is TextBox ||
                   control is RichTextBox ||
                   control is ComboBox ||
                   control is MaskedTextBox;
        }

        // Verifica si la tecla es de control (sin carácter imprimible)
        private bool EsTeclaControl(Keys keyData)
        {
            return keyData == Keys.Back ||
                   keyData == Keys.Delete ||
                   keyData == Keys.Tab ||
                   keyData == Keys.Escape ||
                   keyData == Keys.Space ||
                   keyData == Keys.LMenu || // Alt
                   keyData == Keys.RMenu ||
                   keyData == Keys.LWin || // Windows
                   keyData == Keys.RWin ||
                   keyData == Keys.ControlKey ||
                   keyData == Keys.ShiftKey ||
                   (keyData >= Keys.F1 && keyData <= Keys.F12);
        }


        private bool _basePagoAbierto = false;

        protected override bool ProcessCmdKey(ref System.Windows.Forms.Message msg, Keys keyData)
        {

            // 🔴 BLOQUEO GLOBAL: Si BasePagos está abierto, no proceses NADA
            if (_basePagoAbierto)
            {
                // Opcional: log para depuración
                Control.Common.Logger.LogMessage(
                    Control.Common.Enum.LogTypes.Info,
                    "MainWindows", "ProcessCmdKey",
                    "BasePagos está abierto: bloqueando todas las teclas");

                return true; // 🔥 Consume la tecla, no la propagues
            }


            Control.Common.Logger.LogMessage(
                Control.Common.Enum.LogTypes.Info, "MainWindows", "ProcessCmdKey", "Inicia ProcessCmdKey");

            var controlActual = this.ActiveControl;

            if (controlActual == null)
            {
                Control.Common.Logger.LogMessage(
                    Control.Common.Enum.LogTypes.Info, "MainWindows", "ProcessCmdKey", "controlActual is null");
                return base.ProcessCmdKey(ref msg, keyData);
            }

            // 🔴 BLOQUEAR si el foco está en txtCodigo: dejar que sea txtCodigo_KeyPress quien maneje
            if (controlActual == txtCodigo)
            {
                // Permitir que el TextBox maneje sus teclas normalmente
                return base.ProcessCmdKey(ref msg, keyData);
            }

            // 2. Evitar interferir con otros campos editables (TextBox, etc.)
            if (EsCampoEditable(controlActual))
            {
                return base.ProcessCmdKey(ref msg, keyData);
            }

            // 3. Procesar Enter: código de barras desde buffer
            if (keyData == Keys.Enter)
            {
                if (_isProcessing)
                {
                    Control.Common.Logger.LogMessage(
                        Control.Common.Enum.LogTypes.Info, "MainWindows", "ProcessCmdKey", "Ya está procesando. Evitando reentrada.");
                    return true; // Bloquear
                }

                _isProcessing = true;
                Control.Common.Logger.LogMessage(
                    Control.Common.Enum.LogTypes.Info, "MainWindows", "ProcessCmdKey", "Procesando código de barras desde buffer");

                try
                {
                    string codigo = buffer.ToString().Trim();
                    buffer.Clear();

                    if (string.IsNullOrEmpty(codigo))
                    {
                        return base.ProcessCmdKey(ref msg, keyData);
                    }

                    if (codigo.Length < Control.Common.GlobalParameters.MIN_CARACTER_CODIGO_ART)
                    {
                        Control.Common.Logger.LogMessage(
                            Control.Common.Enum.LogTypes.Info,
                            "MainWindows", "ProcessCmdKey",
                            $"Código muy corto: {codigo.Length} caracteres.");
                        return true;
                    }

                    Control.Common.Logger.LogMessage(
                        Control.Common.Enum.LogTypes.Info,
                        "MainWindows", "ProcessCmdKey",
                        $"Procesando código de barras: {codigo}");

                    bool handled = ProcesarCodigoDeBarras(codigo);
                    if (handled)
                    {
                        Control.Common.Logger.LogMessage(
                            Control.Common.Enum.LogTypes.Info,
                            "MainWindows", "ProcessCmdKey",
                            "Código procesado exitosamente.");
                        return true;
                    }
                }
                catch (Exception ex)
                {
                    Control.Common.Logger.LogMessage(
                        Control.Common.Enum.LogTypes.Error,
                        "MainWindows", "ProcessCmdKey",
                        $"Error: {ex.Message}\n{ex.StackTrace}");
                }
                finally
                {
                    _isProcessing = false;
                }

                return base.ProcessCmdKey(ref msg, keyData);
            }

            // 4. Acumular teclas (solo si no es control y no es Enter)
            if (!EsTeclaControl(keyData))
            {
                char? keyChar = ConvertKeyToChar(keyData);
                if (keyChar.HasValue)
                {
                    buffer.Append(keyChar.Value);
                    Control.Common.Logger.LogMessage(
                        Control.Common.Enum.LogTypes.Info,
                        "MainWindows", "ProcessCmdKey",
                        $"Buffer actual: '{buffer}'");
                }
            }

            // 5. Teclas especiales y atajos
            if (ProcesarTeclaDesdeParametro(keyData) || ProcesarAtajosTeclado(keyData))
            {
                return true;
            }

            return base.ProcessCmdKey(ref msg, keyData);
        }




