        private bool ProcesarCodigoDeBarras(string codigoBarra)
        {
            

            if (string.IsNullOrWhiteSpace(codigoBarra))
                return false;

            Control.Common.Logger.LogMessage(
                Control.Common.Enum.LogTypes.Info,
                "MainWindows",
                "ProcesarCodigoDeBarras",
                $"Inicia procesamiento de código de barras: '{codigoBarra}'");

            try
            {
                if (codigoBarra.StartsWith(POS.Control.Common.GlobalParameters.AppMovil_PrefijoUsaApp))
                {
                    Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindows", "ProcessCmdKey", $" Ingresa por validacion de cliente App");

                    KeyPressEventArgs args = new KeyPressEventArgs((char)Keys.Enter);
                    txtCedula_KeyPress(txtCedula.Text, args);
                    return true;
                }
                else if (codigoBarra.StartsWith("%"))
                {
                    Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindows", "ProcessCmdKey", $" Ingresa por vaidacion de clinete ");

                    txtCodigo.Text = string.Empty;
                    KeyPressEventArgs args = new KeyPressEventArgs((char)Keys.Enter);
                    txtCedula_KeyPress(codigoBarra, args);
                    return true;
                }
                else
                {
                    if (!string.IsNullOrEmpty(txtCodigo.Text))
                    {
                        Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindows", "ProcessCmdKey", $" Ejecuta metodo EjecutaConsultaCodigoItem ");

                        EjecutaConsultaCodigoItem(codigoBarra, null);
                        return false; // Permitir procesamiento normal
                    }
                    else
                    {
                        return false;
                    }
                }

            }
            finally
            {
                Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindows", "ProcessCmdKey", $" Finally ProcesarCodigoDeBarras");

            }



        }



        private bool ProcesarTeclaDesdeParametro(Keys keyData)
        {
            var db = new POSEntities();
            var strtecla = keyData.ToString();
            var parkey = db.core_parametro
                .FirstOrDefault(x => x.identificador == "POS_KEYBOARD" && x.valor == strtecla);

            if (parkey == null) return false;

            switch (parkey.parametro2)
            {
                case "GRABARFACTURA":
                    btnGrabar_Click(null, null);
                    return true;

                case "EFECTIVOEXACTO":
                    EfectivoExactoButton = true;
                    string formaPago = "TAR PORTAL";
                    revisarCambioEnTotal(formaPago, formaPago);
                    decimal valorRetante = decimal.Parse(this.lblRestante.Text.Replace("$", ""));
                    txtPagoValor.Text = valorRetante.ToString();
                    flagEjecutaPago = true;
                    EjecutaBotonPago(OrigenBoton.Pago);
                    flagProcesarDsct = false;
                    return true;

                case "REIMPRIMIRVOUCHER":
                    f4();
                    return true;

                case "REIMPRIMIRFACTURA":
                    f8();
                    return true;

                case "CONSULTAPRECIO":
                    btnPrecio_Click(null, null);
                    return true;

                case "CANTIDADPRODUCTO":
                    SelectQtyProduct();
                    return true;

                case "PAGOTCREDITO":
                    btnTCredito_Click(new object(), new EventArgs());
                    return true;

                case "CONSUMIDORFINAL":
                    if (btnCFinal.Enabled == false)
                        Control.Common.General.GetMensajeToList(150);
                    else
                        FinalClient();
                    return true;

                case "PAGOCHEQUE":
                    btnCheque_Click(new object(), new EventArgs());
                    return true;

                case "PAGOSERVICIO":
                    using (var _frm = new POS.Control.CorrBan.PagosServicios())
                        _frm.ShowDialog();
                    return true;

                case "FORMAPAGO":
                    this.btnPagar_Click(new object(), new EventArgs());
                    return true;

                case "ADMINISTRADOR":
                    f10();
                    return true;

                default:
                    return false;
            }
        }

        private bool ProcesarAtajosTeclado(Keys keyData)
        {
            var db = new POSEntities();

            switch (keyData)
            {
                case Keys.Space when esFactura:
                    btnBusqProd_Click(new object(), new EventArgs());
                    return true;

                case Keys.F1:
                    f1(); // Arqueo para auditores
                    return true;

                case Keys.F2:
                    f2(); // Cierre de caja
                    return true;

                case Keys.F4:
                    if (db.core_parametro.Any(x =>
                        x.identificador == "PINPAD" &&
                        x.parametro2 == this._factura.Establecimiento &&
                        x.valor == "TRUE"))
                    {
                        f4();
                    }
                    else
                    {
                        Control.Common.General.GetMensajeToList(151);
                    }
                    return true;

                case Keys.F5:
                    btnGrabar_Click(null, null);
                    return true;

                case Keys.F6:
                    f6(); // Reporte cierre parcial
                    return true;

                case Keys.F7:
                    var result = Control.Common.General.GetMensajeToList(587); // Confirmación
                    if (result == MsgBoxCtrl.MessageBoxResult.Yes || result == MsgBoxCtrl.MessageBoxResult.Ok)
                    {
                        RecargarParametrosPOS();
                        listPromociones = getPromociones(_factura.Establecimiento);
                        _factura.PromocionesActuales = listPromociones;
                        Control.Common.General.GetMensajeToList(588); // Éxito
                    }
                    return true;

                case Keys.F8:
                    if (db.core_parametro.Any(x =>
                        x.identificador == "REIMPRIME_FACTURA" &&
                        x.parametro2 == this._factura.Establecimiento &&
                        x.valor == "TRUE"))
                    {
                        f8();
                    }
                    else
                    {
                        Control.Common.General.GetMensajeToList(590);
                    }
                    return true;

                case Keys.F9:
                    SelectQtyProduct();
                    return true;

                case Keys.F10:
                    f10(); // Abre ToolBox
                    return true;

                case Keys.F12:
                    if (btnCFinal.Enabled == false)
                        Control.Common.General.GetMensajeToList(589);
                    else
                        FinalClient();
                    return true;

                default:
                    return false;
            }
        }

        private char? ConvertKeyToChar(Keys keyData)
        {
            // Extrae solo la tecla física, ignorando modificadores (Shift, Ctrl, Alt)
            Keys keyCode = keyData & Keys.KeyCode;

            // Letras A-Z (funciona con o sin Shift)
            if (keyCode >= Keys.A && keyCode <= Keys.Z)
            {
                return (char)('A' + (keyCode - Keys.A));
            }

            // Números del teclado principal: D0 a D9 (0-9)
            if (keyCode >= Keys.D0 && keyCode <= Keys.D9)
            {
                return (char)('0' + (keyCode - Keys.D0));
            }

            // Números del teclado numérico
            if (keyCode >= Keys.NumPad0 && keyCode <= Keys.NumPad9)
            {
                return (char)('0' + (keyCode - Keys.NumPad0));
            }

            // Guion '-' (teclado normal o numérico)
            if (keyCode == Keys.OemMinus || keyCode == Keys.Subtract)
            {
                return '-';
            }

            // Punto '.' (teclado normal o numérico)
            if (keyCode == Keys.OemPeriod || keyCode == Keys.Decimal)
            {
                return '.';
            }

            // Barra '/' (teclado numérico)
            if (keyCode == Keys.Divide)
            {
                return '/';
            }

            // Espacio
            if (keyCode == Keys.Space)
            {
                return ' ';
            }

            // Caracteres especiales con Shift
            // Nota: Dependen del diseño del teclado (ej: ES, US)
            if (keyData == (Keys.Shift | Keys.D6)) // Shift + 6 → ^
            {
                return '^';
            }

            if (keyData == (Keys.Shift | Keys.D5)) // Shift + 5 → %
            {
                return '%';
            }

            if (keyData == (Keys.Shift | Keys.D2)) // Shift + 2 → @
            {
                return '@';
            }

            if (keyData == (Keys.Shift | Keys.D3)) // Shift + 3 → #
            {
                return '#';
            }

            // Signo de interrogación ? (puede ser Shift + / en algunos teclados)
            if (keyCode == Keys.OemQuestion)
            {
                return '?';
            }

            // Puedes agregar más según necesites: &, *, etc.

            return null; // No es un carácter válido para código de barras
        }



