        private void RecargaListaMensajes()
        {

            Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindows", "RecargaListaMensajes", " Recarga lista de Mensajes POS ");

            try
            {
                // Control.Common.General.ListMensaje;
                //Control.Common.General.AgregaDetalleMensajesTmpFile(mensajes);
                Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Error, "MainWindow", "RecargaListaMensajes", "Cargando lista de mensajes");
                var mensajes = Control.Common.General.GetListMensaje();

                if (mensajes.ToList().Count() == 0)
                {

                    Control.Common.General.GetMensaje("POS", "No se han cargado el listado de Mensajes. Por favor, comunicarse con Sistemas.", "I");
                    Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Error, "MainWindow", "RecargaListaMensajes", "No se han cargado los mensajes. Favor comunicar a Sistemas");
                }
                Control.Common.General.AgregaDetalleMensajesTmpFileXML(mensajes);


            }
            catch (Exception ex)
            {
                Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindows", "RecargaListaMensajes", $" error al cargar la Lista de Mensajes POS: {ex.Message} ");
            }
        }

