        private void RecargaParametrosWallpapersClte()
        {
            RutaImagen rutaImagenCltes = new RutaImagen();
            List<RutaImagen> listRutaImagenClte = new List<RutaImagen>();
            Control.Common.GlobalParameters.ListWallPapersCltes = new List<RutaImagen>();

            using (var db = new POSEntities())
            {
                if (Control.Common.GlobalParameters.PANTALLA_CLIENTE)
                {

                    var WallPaperClteList = (from deta in db.core_parametro
                                             where deta.identificador.Equals("WALLPAPERCLTE_" + Control.Common.GlobalParameters.EstablecimientoAxCode)
                                             select deta).ToList();



                    if (WallPaperClteList.Count() > 0)
                    {
                        var DetWallPaperClte = WallPaperClteList.FirstOrDefault();

                        var WallPaperClte = (from deta in db.core_parametro
                                             where deta.identificador == "DETWALLPAPERCLTE"
                                             && deta.valor == DetWallPaperClte.id.ToString()
                                             select new
                                             {
                                                 Establecimiento = Control.Common.GlobalParameters.Establecimiento,
                                                 EstablecimientoAxCode = Control.Common.GlobalParameters.EstablecimientoAxCode,
                                                 Ruta = deta.parametro2
                                             }).ToList();

                        if (WallPaperClte.Count >= 1)
                        {
                            foreach (var deta in WallPaperClte)
                            {
                                rutaImagenCltes = new RutaImagen();
                                rutaImagenCltes.Establecimiento = deta.Establecimiento;
                                rutaImagenCltes.Ruta = deta.Ruta;
                                rutaImagenCltes.EstablecimientoAxCode = deta.EstablecimientoAxCode;
                                rutaImagenCltes.imgenEstablecimiento = Image.FromFile(rutaImagenCltes.Ruta);

                                listRutaImagenClte.Add(rutaImagenCltes);
                            }
                        }
                        else
                        {
                            rutaImagenCltes = new RutaImagen();
                            rutaImagenCltes.Establecimiento = Control.Common.GlobalParameters.Establecimiento;
                            rutaImagenCltes.EstablecimientoAxCode = Control.Common.GlobalParameters.EstablecimientoAxCode;
                            rutaImagenCltes.Ruta = @"\\srvatila\Shares\Compartido\ImgPOS\WallpaperClte_Pollo_horno.jpg";
                            rutaImagenCltes.imgenEstablecimiento = Image.FromFile(rutaImagenCltes.Ruta);
                            listRutaImagenClte.Add(rutaImagenCltes);
                        }
                    }
                    else
                    {

                        rutaImagenCltes = new RutaImagen();
                        rutaImagenCltes.Establecimiento = Control.Common.GlobalParameters.Establecimiento;
                        rutaImagenCltes.EstablecimientoAxCode = Control.Common.GlobalParameters.EstablecimientoAxCode;
                        rutaImagenCltes.Ruta = @"\\srvatila\Shares\Compartido\ImgPOS\WallpaperClte_Pollo_horno.jpg";
                        rutaImagenCltes.imgenEstablecimiento = Image.FromFile(rutaImagenCltes.Ruta);
                        listRutaImagenClte.Add(rutaImagenCltes);
                    }
                    Control.Common.GlobalParameters.ListWallPapersCltes = listRutaImagenClte;
                }

            }

        }
        private void RecargaParametrosWallpapersCajero()
        {


            RutaImagen rutaImagen = new RutaImagen();
