            using (var db = new POSEntities())
            {
                var WallPaper = (from deta in db.core_parametro
                                 where deta.identificador.Equals("WALLPAPER_" + Control.Common.GlobalParameters.EstablecimientoAxCode)
                                 select deta).ToList();


                if (WallPaper.Count > 0)
                {
                    var DetWallPaperCajero = WallPaper.FirstOrDefault();

                    var DetWallPaper = (from deta in db.core_parametro
                                        where deta.identificador == "DETWALLPAPER"
                                        && deta.valor == DetWallPaperCajero.id.ToString()
