                            rutaImagen.Ruta = deta.Ruta;
                            rutaImagen.EstablecimientoAxCode = deta.EstablecimientoAxCode;
                            rutaImagen.imgenEstablecimiento = Image.FromFile(rutaImagen.Ruta);
                            listRutaImagen.Add(rutaImagen);
