        private void RecalcularDescuentosPromocionales()
        {
            const string metodo = "RecalcularDescuentosPromocionales";
            Control.Common.Logger.LogMessage(
                Control.Common.Enum.LogTypes.Info,
                "MainWindow",
                metodo,
                "Iniciando recálculo de descuentos promocionales");

            if (_factura == null || _factura.Productos == null || !_factura.Productos.Any())
                return;

            foreach (var producto in _factura.Productos)
            {
                producto.actualizarDescuentoPromocionAX(
                    _factura.PromocionesActuales,
                    _factura.ClienteIdentificacion,
                    _factura
                );
            }

            // Recalcular totales de la factura
            calcularFactura();

            Control.Common.Logger.LogMessage(
                Control.Common.Enum.LogTypes.Info,
                "MainWindow",
                metodo,
                "Recálculo de descuentos promocionales completado");
        }
