        private void imprimeTicketDevolcionIVA(string codigo, string msj, string cliente, string nombreClte, string origen)
        {
            string title = string.Empty;
            string identicador = string.Empty;
            string recibo = string.Empty;




            title = "REVERSO DEVOLUCION IVA ";
            identicador = "T_REVERSO_DEVOLUCION_IVA";

            if (origen == "APLICA_DEV")
            {
                title = "APLICA DEVOLUCION IVA";
                identicador = "T_DEVOLUCION_IVA";
            }

            var pos = new POSEntities();
            var ticket = (from deta in pos.core_recibo
                          where deta.identificador.Trim() == identicador.Trim() // <-- ¡USA TRIM()!
                          select deta).FirstOrDefault();


            StringBuilder lineas_impresion = new StringBuilder();
            if (ticket != null)
            {
                recibo = ticket.cuerpo;

                recibo = recibo.Replace("<<title>>", title);
                recibo = recibo.Replace("<<cedula>>", cliente);
                recibo = recibo.Replace("<<cliente>>", nombreClte);
                recibo = recibo.Replace("<<fecha>>", DateTime.Now.ToString());
                recibo = recibo.Replace("<<monto>>", _factura.montoIvaDevolver.ToString("N2"));
                //recibo = recibo.Replace("<<numero_factura>>", _factura.GetNumeroFactura());
                printer.TextToPrint = recibo.ToString();
                printer.Print();
                //Control.Common.Printer.Imprimir(_factura.Recibo, 3, 11);

            }
            else
            {
                addCL(printer, lineas_impresion, " ");
                addCL(printer, lineas_impresion, "                LIRIS S.A.");
                addCL(printer, lineas_impresion, "            RUC 0990865477001    ");
                addCL(printer, lineas_impresion, "      CONTRIBUYENTE ESPECIAL      ");
                addCL(printer, lineas_impresion, "==================================");
                addCL(printer, lineas_impresion, $"          {title}   ");
                addCL(printer, lineas_impresion, "==================================");
                addCL(printer, lineas_impresion, " CED/RUC: " + cliente);
                addCL(printer, lineas_impresion, " NOMBRE: " + nombreClte);
                addCL(printer, lineas_impresion, "  FECHA: " + DateTime.Now.ToString());
                addCL(printer, lineas_impresion, "==================================");
                addCL(printer, lineas_impresion, $" {msj} ");

                addCL(printer, lineas_impresion, " ");
                addCL(printer, lineas_impresion, " ");
                addCL(printer, lineas_impresion, " ");
                addCL(printer, lineas_impresion, " ");

                printer.TextToPrint = lineas_impresion.ToString();

                Control.Common.Logger.LogMessage(
                                    Control.Common.Enum.LogTypes.Error,
                                    "MainWindows.imprimeTicketReversaDevolcion",
                                    "imprimeTicketReversaDevolcion",
                                    $" printer.TextToPrint {printer.TextToPrint}"
                                );

                printer.Print();

            }


        }
