            addCL(printer, lineas_impresion, " NOMBRE: " + nombreClte);
            addCL(printer, lineas_impresion, "  FECHA: " + DateTime.Now.ToString());
            addCL(printer, lineas_impresion, "==================================");
            addCL(printer, lineas_impresion, $" {msj} ");

            addCL(printer, lineas_impresion, " ");
            addCL(printer, lineas_impresion, " ");
            addCL(printer, lineas_impresion, " ");
            addCL(printer, lineas_impresion, " ");

            printer.TextToPrint = lineas_impresion.ToString();

            Control.Common.Logger.LogMessage(
                              Control.Common.Enum.LogTypes.Error,
                              "MainWindows.imprimeTicketReversaDevolcion",
                              "imprimeTicketReversaDevolcion",
                              $" printer.TextToPrint {printer.TextToPrint}"
                          );

            printer.Print();
        }


        private void getProductoAnt(string codigo, bool debeValidarParqueo = true)
