                    if (SALTARPRODUCTOETIQUETA && ListaCategoriaSaltarItemxEtiqueta.Contains(existente.Categoria.ToUpper()))
                    {
                        validaPeso = false;
                        peso = 0;
                    }

                    if (validaPeso)
                    {
                        while (peso <= 0)
                        {
                            peso = tomarPeso(existente);// decimal.Round(tomarPeso(existente), 2);
