        private void getProducto(string codigo, bool debeValidarParqueo = true)
        {
            List<ParametrosMensajes> parametros = new List<ParametrosMensajes>();

            // Validación inicial
            if (string.IsNullOrWhiteSpace(codigo)) return;

            try
            {
                // 1. Normalización del código
                codigo = NormalizarCodigo(codigo);
                if (!PermiteAgregarItemPorParqueo(codigo)) return;

                // 2. Extraer operador (JCanarte 5Ene2021)
                string operador = ObtenerOperador(codigo);

                // 3. Determinar si es producto existente o nuevo
                if (existeEnLista(codigo))
                {
                    ManejarProductoExistente(codigo, operador);
                }
                else
                {
                    ManejarNuevoProducto(codigo, operador);
                }


                // 4. Aplicar promociones personalizadas
                Control.Common.Logger.LogMessage(
                   Control.Common.Enum.LogTypes.Error,
                   "MainWindows",
                   "getProducto",
                   $"Ejecuta AplicarPromocionesPersonalizadas");

                AplicarPromocionesPersonalizadas(codigo);


                // 5. Validar códigos especiales (cupones de descuento)
                Control.Common.Logger.LogMessage(
                   Control.Common.Enum.LogTypes.Error,
                   "MainWindows",
                   "getProducto",
                   $"Ejecuta ValidarCodigoConDescuento");
                ValidarCodigoConDescuento(codigo);

                // 6. Recalcular y refrescar UI
                Control.Common.Logger.LogMessage(
                   Control.Common.Enum.LogTypes.Error,
                   "MainWindows",
                   "getProducto",
                   $"Ejecuta CalcularFacturaYRefrescar");
                CalcularFacturaYRefrescar(debeValidarParqueo);

                // 7. Guardar en archivo temporal
                Control.Common.Logger.LogMessage(
                   Control.Common.Enum.LogTypes.Error,
                   "MainWindows",
                   "getProducto",
                   $"Ejecuta GuardarProductoTemporal");
                GuardarProductoTemporal(codigo);
                

            }
            catch (Exception ex)
            {
                Control.Common.Logger.LogMessage(
                   Control.Common.Enum.LogTypes.Error,
                   "MainWindows",
                   "getProducto",
                   $"Error al procesar producto {codigo}: {ex.Message}");
                

                parametros = new List<ParametrosMensajes>();
                parametros.Add(new ParametrosMensajes() { codigo = "[Message]"
                    , valor = ex.Message });

                
                Control.Common.General.GetMensajeToList(999, parametros, ex.StackTrace); // Error genérico
            }

        }

        private string NormalizarCodigo(string codigo)
        {
            if (codigo.StartsWith("F"))
                codigo = codigo.Substring(1);
            return codigo.ToUpper();
        }

        private string ObtenerOperador(string codigo)
        {
            return codigo.Length >= 16 ? codigo.Substring(12, 3) : string.Empty;
        }

        private void ManejarProductoExistente(string codigo, string operador)
        {
            List<ParametrosMensajes> parametros = new List<ParametrosMensajes>();
            var existente = getExistente(codigo);
            AnulaDsctoCompraGratis();

            if (ReversaDevolucionIVA_Items()) return;

            ////Reiniciar descuentos            
            // existente.Descuento = 0M;
            // existente.DescuentoActual = 0M;
            // xistente.DescuentoPorCombinacion = 0M;
            ////JCHID PRUEBA DE ENCERAR LOS DESCUENTOS



            decimal peso = 0M;
            bool validaPeso = !DebeSaltarTomaPeso(existente.Categoria);

            if (validaPeso)
            {
                while (peso <= 0)
                {
                    peso = tomarPeso(existente);
                    if (peso == 0)
                    {
                        parametros = new List<ParametrosMensajes>();
                        parametros.Add(new ParametrosMensajes() { codigo = "[codigo]", valor = codigo });
                        Control.Common.General.GetMensajeToList(580, parametros);
                    }
                }
            }

            decimal pesobascula;
            validaPesoCajaBascula(existente, codigo, peso, out pesobascula);

            if (pesobascula <= 0)
            {
                //MostrarErrorPeso(codigo);
                parametros = new List<ParametrosMensajes>();
                parametros.Add(new ParametrosMensajes() { codigo = "[codigo]", valor = codigo });
                Control.Common.General.GetMensajeToList(602, parametros);

                return;
            }

            // Ajustar cantidad
            int ext = existente.qtyBar;
            if (ext > 0)
            {
                existente.Cantidad += ext;
                existente.CantidadINEC = existente.Cantidad;
                existente.Unidades += ext;
            }
            else
            {
                existente.agregarAdicional(pesobascula + (getCantidadXCaja(codigo) - 1));
            }

            // Aplicar promociones
            AplicarPromocionesAX(existente, codigo);  //para los promociones y descuentos en AX

            //// ⚠️ Validar si ya se aplicó cupón antes de update
            //bool yaTieneCupon = existente.DescuentosCupon != null &&
            //                    existente.DescuentosCupon.Any(d => d.codigo == _factura.CuponPromocionalCodigo);

            bool yaTieneCupon = existente.DescuentosCupon != null ? true : false;

            if (yaTieneCupon)
            {
                Control.Common.Logger.LogMessage(
                    Control.Common.Enum.LogTypes.Info,
                    "Producto",
                    "update",
                    $"El cupón '{_factura.CuponPromocionalCodigo}' ya está aplicado en este producto. No se recalculan descuentos normales.");

                // Llamar a update sin recalcular descuentos normales (si tu método acepta parámetro)
                existente.update(false);
            }
            else
            {
                // Update normal: aplica descuentos automáticos
                existente.update();
            }

            // Verificar combos y refrescar
            using (var db = new POSEntities())
            {
                if (Habilitado(db, "COMBO_PRODUCTS"))
                    existente.VerifyComboProducts(codigo, _factura);

                if (Habilitado(db, "PROMO_CHOOSE"))
                    refrescar_promocion(codigo);
            }

            // Limpiar descuentos si hay productos
            if (_factura.Descuentos2.Any())
            {
                _factura.Descuentos2.Clear();
                _factura.Pagos.Clear();
            }

            // Reaplicar descuentos acumulados
            // se descomentan estas líneas para que convivan DESCUENTOS PROMOCIÓN Y DESCUENTOS CUPONES opozo
            ReaplicarDescuentosAcumulados(existente);

            //AplicarDescuentoCuponPromocional(existente, codigo);
            AplicarDescuentoCuponPromocional(existente, codigo);
        }
        private void ManejarNuevoProducto(string codigo, string operador)
        {
            using (var db = new POSEntities())
            {
                var producto = new Producto();
                if (!producto.getProducto(codigo, _factura, cliente_actual))
                {
                    if (!codigo.StartsWith("30"))
                    {
                        var parametros = new List<ParametrosMensajes>
                        {
                            new ParametrosMensajes { codigo = "[codigo_articulo]", valor = codigo }
                        };
                        Control.Common.General.GetMensajeToList(123, parametros);
                    }
                    return;
                }

                // Validaciones globales
                if (Control.Common.GlobalParameters.SRI_DEVOLUCION_IVA)
                    ReversaDevolucionIVA_Items();

                AnulaDsctoCompraGratis();

                if (BlockProducts(codigo))
                {
                    Control.Common.General.GetMensajeToList(154);
                    return;
                }

                // Procesar según tipo: peso o unidad
                if (producto.esPeso)
                {
                    ManejarProductoPorPeso(producto, codigo, operador, db);
                }
                else
                {
                    ManejarProductoPorUnidad(producto, codigo, operador, db);
                }

                // Aplicar cupón promocional
                //ReaplicarDescuentosAcumulados(producto);
                AplicarDescuentoCuponPromocional(producto, codigo);
                

            }
        }
        private void ManejarProductoPorPeso(Producto producto, string codigo, string operador, POSEntities db)
        {
            decimal peso = 0M;
            decimal pesobascula = 0M;
            List<ParametrosMensajes> parametros = new List<ParametrosMensajes>();

            if (DebeSaltarTomaPeso(producto.Categoria))
            {
                peso = 0M; // Se obtiene de etiqueta
            }
            else if (Control.Common.GlobalParameters.USA_BALANZA)
            {
                while (peso <= 0)
                {
                    peso = tomarPeso(producto);
                    if (peso == 0)
                    {
                        parametros = new List<ParametrosMensajes>();
                        parametros.Add(new ParametrosMensajes() { codigo = "[codigo]", valor = codigo });
                        Control.Common.General.GetMensajeToList(580, parametros);
                    }
                }
            }

            validaPesoCajaBascula(producto, codigo, peso, out pesobascula);

            if (pesobascula <= 0)
            {
                parametros = new List<ParametrosMensajes>();
                parametros.Add(new ParametrosMensajes() { codigo = "[codigo]", valor = codigo });
                Control.Common.General.GetMensajeToList(602, parametros);

                return;
            }

            producto.CantidadINEC = pesobascula;
            producto.Cantidad = decimal.Round(pesobascula, 2);
            producto.Operador = operador;

            AplicarPromocionesAX(producto, codigo);
            producto.update();

            if (Habilitado(db, "COMBO_PRODUCTS"))
                producto.VerifyComboProducts(codigo, _factura);

            _factura.Productos.Add(producto);

            if (Habilitado(db, "PROMO_CHOOSE"))
                refrescar_promocion(codigo);

            if (_factura.Descuentos2.Any())
            {
                _factura.Descuentos2.Clear();
                _factura.Pagos.Clear();
            }
        }


        private void ManejarProductoPorUnidad(Producto producto, string codigo, string operador, POSEntities db)
        {
            decimal peso = tomarPeso(producto);
            producto.Cantidad = decimal.Round(peso, 2);
            producto.CantidadINEC = peso;

            Control.Common.Logger.LogMessage(
                   Control.Common.Enum.LogTypes.Error,
                   "MainWindows",
                   "ManejarProductoPorUnidad",
                   $"Ejecuta AplicarPromocionesAX");

            AplicarPromocionesAX(producto, codigo);
            producto.update();

            if (Habilitado(db, "COMBO_PRODUCTS"))
                producto.VerifyComboProducts(codigo, _factura);

            _factura.Productos.Add(producto);

            if (Habilitado(db, "PROMO_CHOOSE"))
                refrescar_promocion(codigo);

            if (_factura.Descuentos2.Any())
            {
                _factura.Descuentos2.Clear();
                _factura.Pagos.Clear();
            }
        }


        /// <summary>
        /// Ejecuta las acciones finales después de agregar un producto:
        /// - Recalcula el total de la factura.
        /// - Refresca la vista de productos (grilla).
        /// - Desplaza el scroll hacia el último ítem.
        /// - Opcionalmente valida y recalcula el parqueo vehicular.
        /// </summary>
        /// <param name="debeValidarParqueo">Indica si debe recalcular el parqueo</param>
        private void CalcularFacturaYRefrescar(bool debeValidarParqueo = true)
        {
            try
            {

               
                // 1. Recalcular el total de la factura
                calcularFactura();

                FacturaService.NotificarCambioProductos(_factura.Productos);

                // 2. Refrescar la grilla de productos
                gridItems.SuspendLayout();
                RefrescarGridItems();
                gridItems.ResumeLayout();

                // 3. Desplazar el scroll al último producto agregado
                ScrollLastGridItems();

                // 4. Validar parqueo si está habilitado
                if (debeValidarParqueo)
                {
                    CalcularParqueo();
                }

                // Logging para auditoría
                Control.Common.Logger.LogMessage(
                    Control.Common.Enum.LogTypes.Info,
                    "MainWindows",
                    "CalcularFacturaYRefrescar",
                    $"Factura recalculada. Total: {_factura.Total:F2}, Productos: {_factura.Productos.Count}"
                );
            }
            catch (Exception ex)
            {
                // Evitar que un error en UI bloquee el flujo
                Control.Common.Logger.LogMessage(
                    Control.Common.Enum.LogTypes.Error,
                    "MainWindows",
                    "CalcularFacturaYRefrescar",
                    $"Error al refrescar la interfaz: {ex.Message}"
                );

                // Mostrar mensaje amigable al usuario
                Control.Common.General.GetMensajeToList(998); // "Error al actualizar la pantalla"
            }
        }

