        private void ReaplicarDescuentosAcumulados(Producto producto)
        {
            //var temp = new Producto();
            //if (temp.getProducto(producto.Id, _factura, cliente_actual) && temp.DescuentoActual > 0)
            //{
            //    producto.DescuentoAX = Math.Round(producto.Pvp * producto.Cantidad * temp.DescuentoActual, 2);
            //    producto.update();
            //}

            //if (producto.DescuentoCuponesCaducidad > 0)
            //{
            //    producto.DescuentoAX = producto.DescuentoCuponesCaducidad;
            //    producto.update();
            //}

            //if (producto.DescuentoTarjetasPaviPlan > 0)
            //{
            //    producto.DescuentoAX = producto.DescuentoTarjetasPaviPlan;
            //    producto.update();
            //}

            //if (producto.DescuentoTarjetasCompraGratis > 0)
            //{
            //    producto.DescuentoAX = producto.DescuentoTarjetasCompraGratis;
            //    producto.update();
            //}

            var temp = new Producto();
            if (temp.getProducto(producto.Id, _factura, cliente_actual) && temp.DescuentoActual > 0)
            {
                producto.DescuentoAX = Math.Round(producto.Pvp * producto.Cantidad * temp.DescuentoActual, 2);
                producto.update();
            }
            if (producto.DescuentoCuponesCaducidad > 0)
            {
                producto.DescuentoAX = producto.DescuentoCuponesCaducidad;
                producto.update();
            }
            if (producto.DescuentoTarjetasPaviPlan > 0)
            {
                producto.DescuentoAX = producto.DescuentoTarjetasPaviPlan;
                producto.update();
            }
            if (producto.DescuentoTarjetasCompraGratis > 0)
            {
                producto.DescuentoAX = producto.DescuentoTarjetasCompraGratis;
                producto.update();
            }

        }

        private void AplicarDescuentoCuponPromocional(Producto producto, string codigo)
        {
            //if (!_factura.EsUsoCuponPromocional) return;

            //var otrosProductos = _factura.Productos.Where(x => x.Id != producto.Id);
            //bool esCuponDeOtroProducto = otrosProductos.Any(item =>
            //    item.DescuentosCupon?.Any(c => c.codigo != _factura.CuponPromocionalCodigo) == true);

            //if (!esCuponDeOtroProducto)
            //{
            //    producto.DescuentoAX = producto.SubtotalSinDescuento * _factura.CuponPromocionalPorcDesc;
            //    producto.update();
            //}

            // Aplicar descuento por cupón promocional solo si:
            // - Se está usando un cupón
            // - Ningún otro producto tiene este mismo cupón asignado
            // - El porcentaje de descuento es válido (> 0)

            // Si no hay cupón activo en la factura, salir
            if (!_factura.EsUsoCuponPromocional) return;

            // ✅ 1. Verificar si este producto ya tiene asignado el cupón actual
            if (producto.DescuentosCupon != null &&
                producto.DescuentosCupon.Any(d => d.codigo == _factura.CuponPromocionalCodigo))
            {
                // Ya fue aplicado a este producto → NO volver a aplicar
                return;
            }

            // ✅ 2. Verificar si el cupón ya fue aplicado a ALGÚN producto en la factura
            // (esto evita aplicarlo a múltiples productos distintos)
            bool yaAplicadoEnOtroProducto = _factura.Productos
                .Any(p => p.DescuentosCupon != null &&
                          p.DescuentosCupon.Any(d => d.codigo == _factura.CuponPromocionalCodigo));

            if (yaAplicadoEnOtroProducto)
            {
                // El cupón ya se usó en otro producto → NO aplicar aquí
                return;
            }

            // ✅ 3. ✅ CRÍTICO: Calcular el descuento SOLO PARA UNA UNIDAD
            // Suponiendo que el precio unitario es Pvp (precio por unidad)
            decimal descuentoPorUnidad = producto.Pvp * (_factura.CuponPromocionalPorcDesc / 100M);

            // ✅ 4. Crear registro del descuento en el producto
            var nuevoDescuento = new Descuento
            {
                codigo = _factura.CuponPromocionalCodigo,
                parametro = _factura.CuponPromocionalPorcDesc.ToString(),
                valor = -1 // Valor genérico para indicar que es cupón de producto
            };

            if (producto.DescuentosCupon == null)
                producto.DescuentosCupon = new List<Descuento>();

            producto.DescuentosCupon.Add(nuevoDescuento);

            // ✅ 5. ✅ CRÍTICO: Aplicar el descuento SOLO a una unidad
            producto.DescuentoAX += descuentoPorUnidad; // Solo suma el descuento de 1 unidad

            // ✅ 6. Actualizar el producto
            producto.update();

            // ✅ Opcional: Mensaje informativo
            Control.Common.Logger.LogMessage(
                Control.Common.Enum.LogTypes.Info,
                "MainWindow",
                "AplicarDescuentoCuponPromocional",
                $"Cupón '{_factura.CuponPromocionalCodigo}' aplicado a 1 unidad del producto {producto.Id}. Descuento: {descuentoPorUnidad:C}");
        }
