        /// <summary>
        /// Determina si el producto debe omitir la toma de peso en báscula,
        /// basado en la configuración global y la categoría del producto.
        /// </summary>
        /// <param name="categoria">Categoría del producto (ej: "CARNICERIA")</param>
        /// <returns>True si se debe saltar la toma de peso; false en caso contrario.</returns>
        private bool DebeSaltarTomaPeso(string categoria)
        {
            if (string.IsNullOrWhiteSpace(categoria))
                return false;

            // SALTARPRODUCTOETIQUETA: parámetro global que habilita esta funcionalidad
            // ListaCategoriaSaltarItemxEtiqueta: lista de categorías configuradas para saltar peso
            return SALTARPRODUCTOETIQUETA &&
                   ListaCategoriaSaltarItemxEtiqueta.Contains(categoria.ToUpper());
        }

        /// <summary>
        /// Valida y procesa códigos de barras especiales que representan cupones de descuento.
        /// Soporta dos tipos:
        ///   - "211..." : Descuento por porcentaje sobre producto existente.
        ///   - "30..."  : Cupón de liquidación con porcentaje desde base de datos.
        /// </summary>
        /// <param name="codigo">Código de barras escaneado</param>
        private void ValidarCodigoConDescuento(string codigo)
        {
            if (_factura.aplicaBeneficioDevolucionIVA)
            {
                Control.Common.General.GetMensajeToList(654); // "No se puede aplicar cupón con Devolución de IVA"
                return;
            }

            if (codigo.StartsWith("211"))
            {
                ProcesarCuponTipo211(codigo);
            }
            else if (codigo.StartsWith("30") && codigo.Length == 12)
            {
                ProcesarCuponTipo30(codigo);
            }
        }
        private void ProcesarCuponTipo211(string codigo)
        {
            // Validar longitud mínima: 211 + 6 dígitos + 3 dígitos = 12 caracteres
            if (codigo.Length < 12)
            {
                Control.Common.General.GetMensajeToList(582); // "Código de cupón inválido"
                return;
            }

            string codigoAux = codigo.Substring(3, codigo.Length - 9); // ITEMID base (sin porcentaje ni secuencia)
            string porcdescStr = codigo.Substring(codigo.Length - 6, 3); // Últimos 3 dígitos del porcentaje

            if (!decimal.TryParse(porcdescStr, out decimal porcentaje))
            {
                Control.Common.General.GetMensajeToList(582);
                return;
            }

            porcentaje = Math.Round(porcentaje / 100, 4); // Convertir 10 → 0.10

            using (var db = new POSEntities())
            {
                // Verificar si ya fue usado
                if (db.pos_itembarra_desc.Any(x => x.ITEMBARCODE == codigo))
                {
                    Control.Common.General.GetMensajeToList(581); // "Cupón ya utilizado"
                    return;
                }

                // Buscar producto en la factura actual
                var item = _factura.Productos
                    .FirstOrDefault(p => p.CodigosBarra.Any(cb => cb.codigo == codigoAux));

                if (item == null)
                {
                    Control.Common.General.GetMensajeToList(582); // "No existe producto para este cupón"
                    return;
                }

                // Aplicar descuento
                decimal valorDescuento = item.Pvp * porcentaje;
                item.DescuentoAX += valorDescuento;
                item.update();

                // Registrar uso del cupón
                var registroCupon = new pos_itembarra_desc
                {
                    ITEMBARCODE = codigo,
                    FACTURA = _factura.GetNumeroFactura(),
                    FACTURADO = null // Puedes poner 1, true, o DateTime.Now si el campo lo permite
                };

                db.pos_itembarra_desc.Add(registroCupon);
                db.SaveChanges();

                // Recalcular total
                calcularFactura();

                Control.Common.Logger.LogMessage(
                    Control.Common.Enum.LogTypes.Info,
                    "MainWindows",
                    "ProcesarCuponTipo211",
                    $"Cupón {codigo} aplicado a producto {item.Id}, descuento: {valorDescuento:C}"
                );
            }
        }


        /// <summary>
        /// Ejecuta y agrega los articulos que estan dentro de Dynamics en la tabla tblliquidacion
        /// - Estos son los cupones de alerta de caducidad
        /// </summary>
        /// <param name="codigo">Código del producto escaneado</param>
        private void ProcesarCuponTipo30(string codigo)
        {
            Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindows", "ProcesarCuponTipo30", " inicia ProcesarCuponTipo30");


            string itemId = string.Empty;
            int inactivo = 0;
            decimal porcentaje = 0;
            string facturaPos = string.Empty;

            using (var conexion = new SqlConnection(POS.Properties.Settings.Default.CONECTA_AX))
            {
                Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindows", "ProcesarCuponTipo30", " Apertura conexion AX");
                conexion.Open();

                try
                {
                    Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindows", "ProcesarCuponTipo30", " Consulta cupon tblliquidacion");
                    string query = "SELECT TOP 1 ITEMID, INACTIVO, PORCENTAJE, FACTURAPOS FROM tblliquidacion WHERE CODIGOCUPON = @codigo";
                    using (var cmd = new SqlCommand(query, conexion))
                    {
                        cmd.Parameters.AddWithValue("@codigo", codigo);
                        using (var reader = cmd.ExecuteReader())
                        {
                            if (!reader.Read())
                            {
                                Control.Common.General.GetMensajeToList(582); // "Cupón no encontrado"
                                return;
                            }


                            itemId = reader["ITEMID"].ToString();
                            inactivo = Convert.ToInt32(reader["INACTIVO"]);
                            porcentaje = Convert.ToDecimal(reader["PORCENTAJE"]);
                            facturaPos = reader["FACTURAPOS"].ToString();

                            Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindows", "ProcesarCuponTipo30", $" itemId: {itemId}");
                            Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindows", "ProcesarCuponTipo30", $" inactivo: {inactivo}");
                            Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindows", "ProcesarCuponTipo30", $" porcentaje: {porcentaje}");
                            Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindows", "ProcesarCuponTipo30", $" facturaPos: {facturaPos}");


                        }
                    }
                }
                catch (Exception ex)
                {
                    Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindows", "ProcesarCuponTipo30", $" Error: {ex.Message}; Trace: {ex.StackTrace}");

                    conexion.Close();
                    conexion.Dispose();
                    return;
                }
                finally
                {
                    Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindows", "ProcesarCuponTipo30", " Cierra conexion1");
                    conexion.Close();
                    conexion.Dispose();

                }


            }


            using (POSEntities db = new POSEntities())
            {
                bool existefac = false;
                if (!string.IsNullOrEmpty(facturaPos))
                {
                    var estab = facturaPos.Substring(2, 3);
                    var ptoemi = facturaPos.Substring(6, 3);
                    var numfac = int.Parse(facturaPos.Substring(10, 9));

                    existefac = db.core_factura.Any(x => x.establecimiento == estab && x.punto_emision == ptoemi && x.numero == numfac);
                }

                
                if ((inactivo == 1 && existefac)) // || _factura.Productos.Count(x => x.Id == ItemId) > 0)
                {
                    Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindows", "ProcesarCuponTipo30", " Esta inactivo y se encuentra en factura; Cupon ya fue utilizado");
                    Control.Common.General.GetMensajeToList(603); // "Cupon ya fue utilizado en otra factura"
                    return;
                }
                else
                {
                    txtCodigo.Text = itemId;
                    //txtCodigo_KeyPress(this, new KeyPressEventArgs((char)(Keys.Enter)));
                    Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindows", "ProcesarCuponTipo30", " EjecutaConsultaCodigoItem ");
                    EjecutaConsultaCodigoItem(itemId, this);
                    

                    using (var conexion = new SqlConnection(POS.Properties.Settings.Default.CONECTA_AX))
                    {
                        conexion.Open();
                        Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindows", "ProcesarCuponTipo30", " Apertura Coenxion 2, esto para actualizar los datos del cupon ");

                        try
                        {
                            if (_factura.Productos.Any(x => x.Id == itemId))
                            {
                                var item = _factura.Productos.FirstOrDefault(x => x.Id == itemId);
                                var porcentajedsct = decimal.Round(porcentaje, 2);
                                var descuentoCaducidad = (porcentaje) * item.Pvp;

                                item.DescuentoAX = descuentoCaducidad;
                                item.update();
                                calcularFactura();
                                item.DescuentoCuponesCaducidad += descuentoCaducidad;
                                flagDescuentoBarra = true;

                                Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindows", "ProcesarCuponTipo30", " Inactiva y asigna el número de factura ");
                                String Query1 = "Update tblliquidacion set INACTIVO =1, FacturaPos = '" + _factura.GetNumeroFactura() + "' where CODIGOCUPON = '" + codigo + "'";

                                Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindows", "ProcesarCuponTipo30", $" FacturaPos {_factura.GetNumeroFactura()} ");
                                Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindows", "ProcesarCuponTipo30", $" codigo {codigo} ");

                                Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindows", "ProcesarCuponTipo30", $" update {Query1} ");

                                SqlCommand comandoupd = new SqlCommand(Query1, conexion);
                                comandoupd.ExecuteNonQuery();
                                
                            }
                        }
                        catch (Exception ex)
                        {
                            Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindows", "ProcesarCuponTipo30", $" Error2: {ex.Message}; Trace: {ex.StackTrace}");
                            conexion.Close();
                            conexion.Dispose();
                        }
                        finally
                        {
                            Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindows", "ProcesarCuponTipo30", " Cierra conexion 2");
                            conexion.Close();
                            conexion.Dispose();

                        }

                    }
                }
            }


            Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindows", "ProcesarCuponTipo30", " Fin ProcesarCuponTipo30");

        }
