        private bool existeEnLista(string codigo)
        {

            Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindows", "existeEnLista", " Inicia metodo existeEnLista ");

            if (string.IsNullOrWhiteSpace(codigo))
            {
                Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindows", "existeEnLista", " Código nulo o vacío. Retornando false ");
                return false;
            }

            // Truncar a 13 caracteres si el código es muy largo
            string codigoAct = codigo.Length >= 16
                ? codigo.Substring(0, 13)
                : codigo;

            if (codigo.Length >= 16)
            {
                Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindows", "existeEnLista", 
                     $"Código largo detectado. Usando solo los primeros 13 caracteres: {codigoAct}");
            }

            // Verifica si ya existe el producto por ID o código de barras (con o sin F)
            bool respuesta = _factura.Productos.Any(producto => 
                                    producto.Id == codigoAct ||
                                    producto.CodigosBarra.Any(cb =>
                                                cb.codigo == codigoAct ||
                                                ("F" + cb.codigo) == codigoAct));

            // Si no se encontró y es código de peso, verificar patrón especial
            if (!respuesta &&
                (codigo.StartsWith(Control.Common.GlobalParameters.ProductoIdentificadorItemPeso) ||
                 codigo.StartsWith(Control.Common.GlobalParameters.ProductoIdentificadorItemPesoAlt)))
            {
                Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info,"MainWindows","existeEnLista",
                   "Código de peso detectado. Aplicando lógica especial para productos por peso.");

                respuesta = _factura.Productos.Any(x => x.CodigosBarra.Any(cb =>
                    cb.codigo.Length > 6 && codigoAct.Length > 6 &&
                    cb.codigo.EndsWith("000000") &&
                    cb.codigo == (codigoAct.Substring(0, codigoAct.Length - 6) + "000000")));
            }

            return respuesta;
        }

       

