        public void existeEnListaDescuento(string codigo)
        {
            const string metodo = "existeEnListaDescuento";
            Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindows", metodo,
                $"Buscando en todas las promociones para código: {codigo}");

            // Validar entrada
            if (string.IsNullOrWhiteSpace(codigo))
            {
                Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Warning, "MainWindows", metodo,
                    "Código vacío o nulo");
                return;
            }

            // Obtener ITEMID real
            string itemId = ObtenerItemIdPorCodigo(codigo);
            if (string.IsNullOrEmpty(itemId))
            {
                Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindows", metodo,
                    $"No se encontró ITEMID para el código: {codigo}");
                return;
            }

            // Obtener todas las promociones actuales
            List<Promocion> listaPromociones = _factura.PromocionesActuales;
            if (listaPromociones == null || !listaPromociones.Any()) return;

            // Obtener todas las promociones válidas para este ITEMID (sin filtrar por promoción específica)
            using (var db = new POSEntities())
            {
                pos_itembarra _codBarras = (from p in db.pos_itembarra
                                            where p.ITEMBARCODE == codigo
                                            || p.ITEMID == codigo
                                            select p).FirstOrDefault();

                if (_codBarras == null)
                {
                    _codBarras = (from p in db.pos_itembarra
                                  where p.ITEMBARCODE.StartsWith(codigo.Substring(0, 7))
                                  select p).FirstOrDefault();
                }

                var todasPromocionesItem = db.vw_DescuentosDetalleAX
                    .Where(x => x.ITEMID == itemId && 
                                x.POS == 1) // Solo promociones para POS
                    .OrderByDescending(x => x.DESCUENTO) // Mayor descuento primero
                    .ToList();


                var datosRelacionados = (from r1 in todasPromocionesItem
                                         join r2 in listaPromociones on r1.REFRECID equals r2.RecId
                                         select r1).ToList();

                // De todas las promociones del item, encontrar la mejor aplicable
                var mejorPromocionAplicable = datosRelacionados.FirstOrDefault(x =>
                {
                    if (x.SHOWAPP == 1)
                        return _factura.EsClienteApp; // Requiere que el cliente esté en app
                    return true; // SHOWAPP == 0 → siempre aplicable
                });

                // Si no hay ninguna promoción aplicable, salir
                if (mejorPromocionAplicable == null)
                {
                    Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindows", metodo,
                        $"No hay promoción aplicable para el item {itemId}");
                    return;
                }

                // Ahora: buscar en qué promoción (RecId) está este descuento
                long recIdPromocion = mejorPromocionAplicable.REFRECID;

                // Buscar si esa promoción está en la lista actual
                var promoDestino = listaPromociones.FirstOrDefault(p => p.RecId == recIdPromocion );

                if (promoDestino == null)
                {
                    Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindows", metodo,
                        $"La promoción {recIdPromocion} con mejor descuento no está activa para este caso");
                    return;
                }

                // Inicializar lista si es nula
                if (promoDestino.ListProductos == null)
                    promoDestino.ListProductos = new List<Producto>();

                // Si el producto ya está, no duplicar
                // AQUI ENTRA EN CONFLICTO PORQUE YA EXISTE EN LA LISTA
                // DE LA PROMOCION
                if (promoDestino.ListProductos.Any(p => p.Id == itemId))
                    return;

                // Crear producto con el mejor descuento encontrado
                var producto = new Producto
                {
                    Id = mejorPromocionAplicable.ITEMID,
                    Cantidad = mejorPromocionAplicable.CANTIDAD,
                    CantidadINEC = mejorPromocionAplicable.CANTIDAD,
                    Descuento = mejorPromocionAplicable.DESCUENTO,
                    TieneDescuentoProductoCliente = mejorPromocionAplicable.TIENEDESCUENTO == 1
                };

                // Agregar producto a la promoción que lo incluye
                promoDestino.ListProductos.Add(producto);

                Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindows", metodo,
                    $"Producto {itemId} agregado a promoción {recIdPromocion} con descuento {mejorPromocionAplicable.DESCUENTO}%");
            }
        }

        



        private Producto GetItemExistente(string codigo)
        {
            //Buscar por barcode o por codigo Ax
            Producto item = _factura.Productos.Where(x => x.Id == codigo || x.CodigosBarra.Any(cb =>
                                                            cb.codigo == codigo
                                                            ||
                                                            ("F" + cb.codigo) == codigo)
                                                     )
                                               .FirstOrDefault();

            //Buscar por barcode de peso
            if (item == null)
            {
                if (codigo.StartsWith(Control.Common.GlobalParameters.ProductoIdentificadorItemPeso) || codigo.StartsWith(Control.Common.GlobalParameters.ProductoIdentificadorItemPesoAlt))
                {
                    item = _factura.Productos.Where(x => x.CodigosBarra.Any(cb =>
                                                                ((cb.codigo.Length > 6 && codigo.Length > 6 && cb.codigo.EndsWith("000000")) ? (cb.codigo == (codigo.Substring(0, codigo.Length - 6) + "000000")) : false))
                                                         )
                                                   .FirstOrDefault();
                }
            }

            return item;
        }

        private Producto getExistente(string codigo)
        {
            //Por regla general todos los productos tienen su codigo en mayuscula, se usa TOUPPER para evitar errores por CaseSensitive
            codigo = codigo.ToUpper();
            var codigoBarraComparador = codigo;

            //Este metodo intentara encontrar que el codigo enviado es un codigo de barras en base POS
            Producto p = new Producto();
            pos_item item = p.getProductoPeso(codigo);

            foreach (var i in _factura.Productos)
            {
                foreach (var c in i.CodigosBarra)
                {
                    if (item != null)
                    {
                        using (var db = new POSEntities())
                        {
                            codigoBarraComparador = db.pos_itembarra.First(x => x.ITEMID == item.ITEMID).ITEMBARCODE;
                        }
                    }
                    if (c.codigo == codigoBarraComparador || "F" + c.codigo == codigoBarraComparador)
                    {
                        i.qtyBar = p.qtyBar;
                        return i;
                    }
                }
            }

            return _factura.Productos.Single(x => x.Id == codigo);
        }

        void ShowDesktopAlert(string title, string text, bool autoClose = true,
            int autoCloseDelay = 2, int width = 329, int height = 100, AlertScreenPosition position = AlertScreenPosition.TopCenter)
        {
            RadDesktopAlert alert = new RadDesktopAlert();
            alert.ThemeName = this.ThemeName;
            alert.AutoClose = autoClose;
            alert.AutoCloseDelay = autoCloseDelay;
            alert.FixedSize = new Size(width, height);
            alert.FadeAnimationType = FadeAnimationType.FadeIn | FadeAnimationType.FadeOut;
            alert.CaptionText = title;
            alert.ContentText = text;
            alert.ScreenPosition = position;
            alert.Show();
            alert.Closed += new RadPopupClosedEventHandler(alert_Closed);
        }

