        private bool consultaPromoCompraGratis()
        {
            List<core_promocompragratis> PromoGratis = new List<core_promocompragratis>();
            decimal Disponible = 0;
            bool flagCompraGratis = false;

            try
            {
                using (POSEntities db = new POSEntities())
                {//*****PROMO COMPRA GRATIS******************************************************************************************

                    PromoGratis = (from promo in db.core_promocompragratis
                                   where promo.fecha == DateTime.Today
                                   && promo.Entregado < promo.Cantidad
                                   && (promo.Local == _factura.Establecimiento || promo.Local == null)
                                   select promo).ToList();

                    if (PromoGratis.Count > 0)
                    {
                        Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Error, "MainWindow", "btnPagar_click", "consultaPromoCompraGratis - Se ha encontrado registro para compraGratis ");

                        foreach (var desc in PromoGratis)
                        {
                            Disponible = desc.Cantidad - desc.Entregado;

                            if (_factura.GetTotal() >= desc.TotalFacDesde && _factura.GetTotal() <= desc.TotalFacHasta && _factura.GetTotal() <= Disponible && !flagCompraGratis)
                            {
                                var Parametros = new List<core_parametro>();
                                Parametros = db.core_parametro.Where(x => x.identificador == "PROMO_COMPRAGRATIS_HORA").ToList();
                                var RangoDefault = db.core_parametro.Where(x => x.identificador == "PROMO_COMPRAGRATIS_RANDON").FirstOrDefault();
                                int RangoRandom = int.Parse(RangoDefault.valor);
                                int suerte = 0;

                                foreach (var Parm in Parametros)
                                {
                                    if (DateTime.Now >= DateTime.Parse(Parm.valor) && DateTime.Now <= DateTime.Parse(Parm.valor).AddMinutes(140))
                                    {
                                        RangoRandom = int.Parse(Parm.parametro2);
                                    }
                                }

                                Random rnd = new Random();
                                suerte = rnd.Next(RangoRandom);

                                if (suerte == 1)
                                {
                                    try
                                    {
                                        SmtpClient server = new SmtpClient("smtp.gmail.com", 587);
                                        server.Credentials = new System.Net.NetworkCredential("tecworkec@gmail.com", "Ecuador1");
                                        server.EnableSsl = true;
                                        MailMessage mnsj = new MailMessage();
                                        mnsj.Subject = "COMPRA GRATIS ";
                                        mnsj.To.Add(new MailAddress("devteam@liris.com.ec"));
                                        mnsj.CC.Add(new MailAddress("amolestina@liris.com.ec"));
                                        //mnsj.From = new MailAddress("tecworkec@gmail.com", "LIRIS COMPRA_GRATIS");
                                        mnsj.Body = "Ganador con una Factura de: $" + _factura.GetTotal() + " Factura No: " + _factura.GetNumeroFactura();
                                        server.Send(mnsj);

                                    }
                                    catch (Exception ex)
                                    {
                                        Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Error, "MainWindow", "btnPagar_click", "consultaPromoCompraGratis - No se pudo enviar correo de ganador de compra gratis, a continuacion las excepciones encontradas - " + Control.Common.ExceptionHandler.GetExceptionMessages(ex));
                                    }

                                    DialogResult dr = new DialogResult();
                                    Ganador frm = new Ganador();
                                    while (dr != DialogResult.OK && dr != DialogResult.Retry)
                                    {
                                        dr = frm.ShowDialog();

                                    }
                                    switch (dr)
                                    {
                                        case DialogResult.OK:
                                            break;
                                        case DialogResult.Retry:
                                            break;
                                    }



                                    var Promo = db.core_promocompragratis.Single(x => x.id == desc.id);
                                    Promo.Entregado = Promo.Entregado + _factura.GetTotal();
                                    db.SaveChanges();

                                    /*Inserta registro en la core_giftcard */
                                    Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Error, "MainWindow", "btnPagar_click", "consultaPromoCompraGratis - Inserta registro en la core_giftcard");
                                    var giftcard = new core_giftcard();
                                    giftcard.fecha_creacion = DateTime.Now;
                                    giftcard.fecha_modificacion = DateTime.Now;
                                    giftcard.fecha_activacion = DateTime.Now;
                                    giftcard.fecha_expiracion = DateTime.Now.AddDays(1);
                                    giftcard.activo = true;
                                    giftcard.bono = true;
                                    giftcard.codigo = "000" + (_factura.GetNumeroFactura().Replace("-", "")).Replace("F", "");
                                    giftcard.saldo = _factura.GetTotal();
                                    giftcard.monto = 0;
                                    giftcard.tipoTransaccion = "";
                                    giftcard.tipoTransaccionId = 0;

                                    db.core_giftcard.Add(giftcard);
                                    db.SaveChanges();

                                    //Agregar lineas de insert
                                    Control.Common.Logger.Agregar_Trace_Giftcard(giftcard);

                                    _factura.mensaje_promo = "    ¡Has ganado tu compra gratis\n de nuestra promoción tu Caja Sorpresa!\n";
                                    _factura.mensaje_promo = _factura.mensaje_promo + " Tu compra de este momento te la llevas\n      sin pagar ni un centavo.\n";
                                    _factura.mensaje_promo = _factura.mensaje_promo + "    ¡Feliz Navidad con Delportal.\n       Más fresco, Más cerca!";

                                    //Se envia saldo cero porque esta giftcard será usada inmediatamente
                                    _factura.AgregarPagoTarjetaRegalo(_factura.GetTotal(), "000" + (_factura.GetNumeroFactura().Replace("-", "")).Replace("F", ""), 0, false, string.Empty, string.Empty);
                                    btnEliminarPago.Visible = false;
                                    btnPagoAtras.Visible = false;
                                }
                            }
                        }

                        flagCompraGratis = true;//Solo un sorteo
                    }

                    //**************************************************************************************************************************


                }

                return flagCompraGratis;
            }
            catch (Exception)
            {
                flagCompraGratis = false;

            }


            return flagCompraGratis;

        }

        private bool ejecutaReversoDevolucionIVA()
        {
            datosDocumnetos datosDocumentos = new datosDocumnetos();
            List<ParametrosMensajes> parametros = new List<ParametrosMensajes>();
            Screen screenClte = Control.Common.General.GetScreenClte();
            Screen screenCajero = Control.Common.General.GetScreenCajero();

            bool validaReverso = false;

            try
            {
                datosDocumentos.tipoDocumnto = "F";
                datosDocumentos.tipoComprobante = "04";
                datosDocumentos.numSecuencia = _factura.Secuencia;
                datosDocumentos.ruc_matriz = _factura.Ruc_matriz;
                datosDocumentos.claveAccesoComprobante = _factura.ClaveAccesoSRI;
                datosDocumentos.identificacion = _factura.ClienteIdentificacion;
                datosDocumentos.baseImponible = _factura.GetBase12();
                datosDocumentos.montoIva = _factura.getIVA();
                datosDocumentos.montoIvaDevolver = _factura.getIVA();

                var respuestaAnulaDevolucion = EjecutaAnulaDevolucionIVA(datosDocumentos);
                int codMensaje = Int32.Parse(respuestaAnulaDevolucion.codigo);

                if (respuestaAnulaDevolucion.codigo == "6007")
                {

                    string Mensaje = $"Se realiza el Reverso de la Devolución de IVA " +
                            $"\n por {respuestaAnulaDevolucion.montoIvaDevolver:N} \n de la factura";


                    respuestaAnulaDevolucion.mensaje = Mensaje;

                    imprimeTicketDevolcionIVA(
                                    respuestaAnulaDevolucion.codigo,
                                    Mensaje,
                                    _factura.ClienteIdentificacion,
                                    _factura.Cliente_nombre,
                                    "REVERSA_IVA");



                    DevolucionIvaModel devolucionIva = new DevolucionIvaModel();

                    devolucionIva.tipoDocumento = _factura.Documento;
                    devolucionIva.establecimiento = _factura.Establecimiento;
                    devolucionIva.puntoEmision = _factura.PtoEmision;
                    devolucionIva.numDocumento = _factura.Secuencia.ToString();
                    devolucionIva.ClaveAccesoSRI = _factura.ClaveAccesoSRI;
                    devolucionIva.cliente = _factura.ClienteIdentificacion;
                    devolucionIva.estado = "R";

                    Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindow", "ejecutaReversoDevolucionIVA", $"Ejecuta metodo  grabaDevolucionIVA");
                    _factura.grabaDevolucionIVA(devolucionIva);

                    _factura.montoIvaDevolver = 0;
                    _factura.pinClteDevolucion = "";

                    _factura.Documento = "F";
                    string ClaveAccesoSRI = string.Empty;


                    if (Control.Common.GlobalParameters.SRI_ACTIVAR_CLAVE_ACCESO)
                    {
                        ClaveAccesoSRI = _factura.generarClaveAccesoSRI(_factura.Documento);
                    }
                    _factura.ClaveAccesoSRI = ClaveAccesoSRI;


                    //_factura.ClaveAccesoSRI = _factura.generarClaveAccesoSRI(_factura.Documento);

                    Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindows", "getProducto", " reverso de IVA realizado correctamente. ");
                    Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindows", "getProducto", " variables fueron enceradas");
                }
                else
                {

                    switch (codMensaje)
                    {
                        case 6001:
                            parametros = new List<ParametrosMensajes>();
                            parametros.Add(new ParametrosMensajes() { codigo = "[montoIvaDevolver]", valor = respuestaAnulaDevolucion.montoIvaDevolver.ToString() });
                            Control.Common.General.GetMensajeToList(codMensaje, screenClte, parametros); // Mensaje genérico de error

                            break;

                        default:

                            this.BeginInvoke((MethodInvoker)delegate
                            {
                                Control.Common.General.GetMensajeToList(656);
                            });

                            //Task.Run(() =>
                            //{
                            //    Control.Common.General.GetMensajeToList(656);
                            //});
                            break;

                    };

                    validaReverso = false;
                }
            }
            catch (Exception ex)
            {
                validaReverso = true;
                parametros = new List<ParametrosMensajes>();
                parametros.Add(new ParametrosMensajes() { codigo = "[Message]", valor = ex.Message });

                Task.Run(() =>
                {
                    Control.Common.General.GetMensajeToList(999, parametros, ex.StackTrace); // Mensaje genérico de error
                });
            }
         

            return validaReverso;


        }
