                bool flagCompraGratis = consultaPromoCompraGratis();

                //string permite_almacen = db.core_parametro.Where(k => k.identificador == "LOCAL_TAR_DESC" && k.parametro2 == this._factura.Establecimiento).FirstOrDefault().valor;
