                        if (result == MsgBoxCtrl.MessageBoxResult.Ok || result == MsgBoxCtrl.MessageBoxResult.Yes)
                        {
                            btnDescuentoEspecial_Click(sender, e);
                        }
                    }
                }



                if (_factura.esBeneficiarioDevolucionIVA && !_factura.aplicaBeneficioDevolucionIVA)
                {
                    if (_factura.GetBase12() > 0)
                    {
                        if (_factura.montoIvaDevolver == 0)
                        {
                            var resultado = Control.Common.General.GetMensajeToList(650); // Confirmación para aplicar IVA

                            if (resultado == MsgBoxCtrl.MessageBoxResult.Ok || resultado == MsgBoxCtrl.MessageBoxResult.Yes)
