        private bool ControlEstaEnPanel(Panel panel, System.Windows.Forms.Control control)
        {
            return control != null && panel.Contains(control);
        }



        public void EjecutaBotonPago(OrigenBoton origenBtn)
        {
            // Ocultar ambos botones por defecto
            ConfigurarBotones(false, false, false);

            switch (origenBtn)
            {
                case OrigenBoton.Return:
                    ConfigurarBotones(true, false, false);
                    flagEjecutaPago = false;

                    // Evitar colapso si el foco está en Panel2
                    if (!ControlEstaEnPanel(splitDetalle.Panel2, System.Windows.Forms.Control.FromHandle(GetFocus())))
                    {
                        splitDetalle.Panel2Collapsed = true;
                    }

                    if (origenBtn == OrigenBoton.Return) {
                        splitDetalle.Panel2Collapsed = true;
                    }

                    break;

                case OrigenBoton.Pago:
                    ConfigurarBotones(false, true, true);
                    flagEjecutaPago = true;
                    splitDetalle.Panel2Collapsed = false;
                    break;

                default:
                    Control.Common.Logger.LogMessage(
                        Control.Common.Enum.LogTypes.Warn,
                        "MainWindows",
                        "EjecutaBotonPago",
                        $"Parámetro desconocido: {origenBtn}"
                    );
                    break;
            }
        }

        private void ConfigurarBotones(bool mostrarBtnPagar, bool mostrarBtnGrabar, bool habilitarBtnGrabar)
        {
            btnPagar.Visible = mostrarBtnPagar;
            btnGrabar.Visible = mostrarBtnGrabar;
            btnGrabar.Enabled = habilitarBtnGrabar;
        }


        private void SuscribirEventosPanel()
        {
            foreach (System.Windows.Forms.Control ctrl in splitDetalle.Panel2.Controls)
            {
                ctrl.Enter += (s, e) => flagEjecutaPago = true;
                ctrl.Leave += (s, e) => flagEjecutaPago = false;
            }
        }
        private bool ControlEstaEnPanel(System.Windows.Forms.Control panel, System.Windows.Forms.Control controlEnfocado)
        {
            if (controlEnfocado == null) return false;

            System.Windows.Forms.Control current = controlEnfocado;

            while (current != null)
            {
                if (current == panel)
                    return true;

                current = current.Parent;
            }

            return false;
        }

