        private void MostrarFormularioPagoTarjetaNoModal(decimal valorRetante)
        {
            // Capturar posición y tamaño del MainWindow en el hilo principal
            Point mainWindowLocation = this.PointToScreen(Point.Empty);

          
            // Delegado para actualizar UI al finalizar
            MethodInvoker actualizarUI = delegate
            {
                txtPagoValor.Clear();
                calcularFactura();
                agregaFormasPagoTmpFile();
                flagEjecutaPago = true;
                EjecutaBotonPago(OrigenBoton.Pago);
                flagProcesarDsct = false;
            };

            // Hilo secundario
            System.Threading.Thread thread = new System.Threading.Thread(
            new System.Threading.ThreadStart(delegate
            {

                POS.Control.Pagos.BasePagos formPagoTarjeta = null;


                ////MainWindow clonedMainWindow = this;
                //this.Enabled = false;
                //using (var basePago = new POS.Control.Pagos.BasePagos(Control.Pagos.BasePagos.PagoTipo.TarjetaCredito, ref _factura, valorRetante))
                //{
                //    basePago._mainWindow = this;
                //    basePago.StartPosition = FormStartPosition.CenterParent;
                //    basePago.Owner = this;
                //    //basePago._pagoTipo = BasePagos.PagoTipo.NotaCredito;

                //    var result = basePago.ShowDialog(this);
                //    _bloquearFocoEnActivacion = false;
                //    this.Enabled = true;
                //}



                try
                {

                    // === Crear y configurar el formulario ===
                    formPagoTarjeta = new POS.Control.Pagos.BasePagos(
                        POS.Control.Pagos.BasePagos.PagoTipo.TarjetaCredito,
                        ref _factura,
                        valorRetante
                    );


                    // === Prevenir que el MainWindow se active y pase encima ===
                    // Deshabilitar temporalmente el MainWindow (opcional visual)
                    this.Invoke(new MethodInvoker(delegate
                    {
                        this.TopMost = false;
                        this.Enabled = false; // Desactiva el MainWindow (grisado)
                    }));


                    Size screenSize = System.Windows.Forms.Screen.PrimaryScreen.Bounds.Size;
                    Size formSize = formPagoTarjeta.Size;


                    // Calcular posición centrada en la pantalla
                    int x = (screenSize.Width - formSize.Width) / 2;
                    int y = (screenSize.Height - formSize.Height) / 2;

                    // Configuración crítica para que esté encima
                    formPagoTarjeta.StartPosition = FormStartPosition.Manual;
                    formPagoTarjeta.Location = new System.Drawing.Point(
                        x < 0 ? 0 : x,
                        y < 0 ? 0 : y
                    );

                    formPagoTarjeta._mainWindow = this;
                    formPagoTarjeta.TopMost = true;           // Siempre encima
                    formPagoTarjeta.BringToFront();          // Traer al frente
                    formPagoTarjeta.Focus();                 // Intentar enfocar


                    // Mostrar modalmente
                    formPagoTarjeta.ShowDialog();
                }
                catch (Exception ex)
                {
                    try
                    {
                        this.Invoke(new MethodInvoker(delegate
                        {
                            MessageBox.Show(
                                "Error: " + ex.Message,
                                "Error",
                                MessageBoxButtons.OK,
                                MessageBoxIcon.Error);
                        }));
                    }
                    catch { }
                }
                finally
                {
                // Asegurarse de restaurar el estado del MainWindow
                try
                {
                    this.Invoke(new MethodInvoker(delegate
                    {
                        this.TopMost = true;
                        this.Enabled = true;
                        this.BringToFront(); // Evita que quede atrás
                        this.Focus();
                    }));
                }
                catch { }

            // Liberar formulario
                if (formPagoTarjeta != null && !formPagoTarjeta.IsDisposed)
                {
                    try { formPagoTarjeta.Dispose(); } catch { }
                }
            }

            // Actualizar UI después del cierre
            try
                    {
                        this.Invoke(actualizarUI);
                    }
                    catch { }
                })
            );

            // ⚠️ Obligatorio para WinForms
            thread.SetApartmentState(System.Threading.ApartmentState.STA);

            // Iniciar hilo
            thread.Start();
        }

        private void ValidaDescuentoenBines()
        {
            try
            {
                using (POSEntities db = new POSEntities())
                {


                    if (db.core_parametro.Any(x => x.identificador.Equals("DESCUENTO_BINES_TARJETA") && x.parametro2 == POS.Control.Common.GlobalParameters.Establecimiento && x.valor.ToString().ToUpper().Equals("TRUE")))
                    {
                        var paramDsctoBinesTarj = db.core_parametro.Where(x => x.identificador.Equals("DESCUENTO_BINES_TARJETA") && x.parametro2 == POS.Control.Common.GlobalParameters.Establecimiento && x.valor.ToString().ToUpper().Equals("TRUE")).FirstOrDefault();

                        var productosdscto = db.core_parametro.Where(x => x.identificador == "DESCUENTO_BINES_TARJETA_PRODUCTOS" && x.valor == "TRUE").FirstOrDefault();

                        // Si no encuentra en la venta productos configurados no llama a la pantalla promo bines.   JM   19-11-2020
                        if (productosdscto != null)
                        {
                            var list_productos = productosdscto.documento.Split(';');
                            bool existeDscto = FacturaActual.Productos.Select(x => x.Id).Intersect(list_productos).Any();
                            if (!existeDscto)
                                return;
                        }

                        SearchPromoBinesTarj promBines = new SearchPromoBinesTarj();
                        promBines.ShowDialog();


                        DescuentoPromoTarjBines = promBines.DescuentoPromTarjetaBines;
                        aplicaDsctoPromoTarjetaBines = promBines.AplicaPromoTarjBines;
                        binTarjetaPromoDscto = promBines.BinTarjetaPromo;

                        _factura.BinNumeroTarjetaPromo = binTarjetaPromoDscto;
                        
                        agregarDescuentoPromocionTarjetaBines(DescuentoPromoTarjBines);
                    }

                }


            }
            catch (Exception ex)
            {

                Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Error, "MainWindow", "ValidaDescuentoBines", "Ha Ocurrido una Excepción: " + ex.Message);
            }
        }

        public void agregarDescuentoPromocionTarjetaBines(decimal valorDescuento)
        {
            try
            {


                if (_factura != null && _factura.GetTotal() > 0)
                {
                    POSEntities db = new POSEntities();
                    if (aplicaDsctoPromoTarjetaBines)
                    {
                        var valor = 0M;
                        valor = valorDescuento;

                        _factura.agregarPromocionTarjetaBines(valor);
                        aplicaDsctoPromoTarjetaBines = false;
                        calcularFactura();

                    }
                    //}
                }
            }
            catch (Exception ex1)
            {
                Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Error, "MainWindow", "agregarDescuentoPromocionTarjetaBines", "Ha Ocurrido una Excepción: " + ex1.Message);
            }
        }

