        private bool revisarCambioEnTotal(string forma_pago, string codigo)
        {
            if (_factura.Documento == "F")
            {

                if (_factura.aplicaBeneficioDevolucionIVA)
                {
                    var f = new POS.Control.Pagos.CalculoPago(_factura);
                    f.StartPosition = FormStartPosition.CenterScreen;
                    f.ShowDialog();
                    calcularFactura();
                    return true;
                }


                if (_factura.ClienteIdentificacion != null)
                {
                    if (_factura.buscarDescuentosFormaPago(forma_pago, codigo))
                    {
                        var f = new POS.Control.Pagos.CalculoPago(_factura);
                        f.StartPosition = FormStartPosition.CenterScreen;
                        f.ShowDialog();
                        calcularFactura();
                        return true;
                    }
                }
            }
            return false;
        }



        private bool ValidacionBeneficioIVA(string origen)
        {
            Screen screenClte = Control.Common.General.GetScreenClte();
            Screen screenCajero = Control.Common.General.GetScreenCajero();
            List<ParametrosMensajes> parametros = new List<ParametrosMensajes>();


            decimal totalFactura = decimal.Parse(this.lblTotal2.Text.Replace("$", ""));
            decimal valorRestante = decimal.Parse(this.lblRestante.Text.Replace("$", ""));
            decimal PagoValor = 0;
            if (this.txtPagoValor.Text != "") { PagoValor = decimal.Parse(this.txtPagoValor.Text.Replace("$", "")); }

            decimal valorIngresado = 0M;
            decimal.TryParse(txtPagoValor.Text, out valorIngresado);


            Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Error, "MainWindow", "ValidacionBeneficioIVA", $"_factura.esBeneficiarioDevolucionIVA: {_factura.esBeneficiarioDevolucionIVA}");
            Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Error, "MainWindow", "ValidacionBeneficioIVA", $"_factura.aplicaBeneficioDevolucionIVA: {_factura.aplicaBeneficioDevolucionIVA}");

            // Validar si el cliente es beneficiario de devolución del IVA
            if (_factura != null && _factura.aplicaBeneficioDevolucionIVA && _factura.esBeneficiarioDevolucionIVA)
            {

                if (Control.Common.GlobalParameters.SRI_ACTIVAR_CLAVE_ACCESO == false)
                {
                    
                    Control.Common.General.GetMensajeToList(678);
                    return false;
                }


                //_factura.ClaveAccesoSRI = _factura.generarClaveAccesoSRI("F");

                //string ClaveAccesoSRI = string.Empty;

                //if (Control.Common.GlobalParameters.SRI_ACTIVAR_CLAVE_ACCESO)
                //{
                //    Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindows", "getProducto", " Regenera Clave de Acceso.");
                //    ClaveAccesoSRI = _factura.generarClaveAccesoSRI(_factura.Documento);
                //}

                //_factura.ClaveAccesoSRI = ClaveAccesoSRI;

                //jchid
                if (string.IsNullOrEmpty(_factura.ClaveAccesoSRI))
                {
                    _factura.ClaveAccesoSRI = _factura.generarClaveAccesoSRI("F");
                }


                var fPagoEfec = (from deta in _factura.Pagos
                                 where deta.Descripcion != "EFECTIVO"
                                 select deta).ToList();


                var PagoEfec = (from deta in _factura.Pagos
                                where deta.Descripcion == "EFECTIVO"
                                select deta).ToList();


                if (fPagoEfec.Count > 0)
                {
                    Control.Common.General.GetMensajeToList(658);
                    return false;
                }

                if (PagoEfec.Count > 0)
                {
                    var pagoRealizado = PagoEfec.FirstOrDefault().Valor;
                    if ((totalFactura - pagoRealizado) > 0)
                    {
                        Control.Common.General.GetMensajeToList(659);
                        return false;
                    }
                }


                if (_factura.GetBase12() == 0)
                {
                    Control.Common.General.GetMensajeToList(660);
                    return false;
                }


                if (origen == "btnEfectivo")
                {
                    if (valorIngresado < totalFactura)
                    {
                        Control.Common.General.GetMensajeToList(652);
                        flagEjecutaPago = true;
                        EjecutaBotonPago(OrigenBoton.Pago);
                        flagProcesarDsct = false;
                        return false;
                    }

                }


                int codMensaje = 0;
                Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Error, "MainWindow", "ValidacionBeneficioIVA", $"_factura.montoIvaDevolver: {_factura.montoIvaDevolver}");

                if (_factura.montoIvaDevolver == 0)
                {

                    int reintento = 0;
                    int maxReintentos = 3;
                    RespuestaDevlucion respuestaDevIVA = new RespuestaDevlucion();
                    

                    do
                    {
                        respuestaDevIVA = EjecutaDevolucionIVA();

                        // Si después de los reintentos sigue devolviendo 3001
                        if (respuestaDevIVA.codigo == "3007")
                        {
                            // Manejo del error después de reintentar N veces
                            Task.Run(() => Control.Common.General.GetMensajeToList(3007, screenCajero));
                            Task.Run(() => Control.Common.General.GetMensajeToList(3007, screenClte));
                            reintento++;
                        }
                        else
                        {
                            // valida si el codigo es -99, significa que cancelo / cerro
                            if (respuestaDevIVA.codigo == "-999")
                                return false;
                            // Si el código no es 3001, salimos del bucle
                            if (respuestaDevIVA.codigo != "3007")
                                break;


                        }

                    } while (reintento < maxReintentos);


                    if (reintento == maxReintentos)
                    {
                        Task.Run(() => Control.Common.General.GetMensajeToList(668, screenClte));
                        return false;
                    }

                    // Continuamos con el resto del flujo
                    codMensaje = Int32.Parse(respuestaDevIVA.codigo);

                    if (respuestaDevIVA.codigo == "2000")
                    {
                        _factura.aplicaBeneficioDevolucionIVA = true;
                        _factura.ClaveAccesoSRI = respuestaDevIVA.claveAccesoComprobante;
                        _factura.montoIvaDevolver = respuestaDevIVA.montoIvaDevolver;
                        _factura.pinClteDevolucion = respuestaDevIVA.pinClteDevolucion;

                        string Mensaje = $"Se aplica Devolución de IVA por $ {respuestaDevIVA.montoIvaDevolver:N} \n de la factura";

                        imprimeTicketDevolcionIVA(
                            respuestaDevIVA.codigo,
                            Mensaje,
                            _factura.ClienteIdentificacion,
                            _factura.Cliente_nombre,
                            "APLICA_DEV");

                        Task.Run(() =>
                        {
                            parametros.Add(new ParametrosMensajes()
                            {
                                codigo = "[montoIvaDevolver]",
                                valor = respuestaDevIVA.montoIvaDevolver.ToString("N")
                            });

                            Control.Common.General.GetMensajeToList(codMensaje, screenClte, parametros);
                        });
                    }
                    else
                    {
                        bool ejecutaReverso = new[] { "-1", "-2", "-3" }.Contains(respuestaDevIVA.codigo);
                        if (ejecutaReverso)
                        {
                            datosDocumnetos datosDocumentos = new datosDocumnetos()
                            {
                                tipoDocumnto = "F",
                                tipoComprobante = "04",
                                numSecuencia = _factura.Secuencia,
                                ruc_matriz = _factura.Ruc_matriz,
                                claveAccesoComprobante = _factura.ClaveAccesoSRI,
                                identificacion = _factura.ClienteIdentificacion,
                                baseImponible = _factura.GetBase12(),
                                montoIva = _factura.getIVA(),
                                montoIvaDevolver = _factura.getIVA()
                            };

                            var respuestaAnulaDevolucion = EjecutaAnulaDevolucionIVA(datosDocumentos);

                            if (respuestaAnulaDevolucion.codigo == "6007")
                            {
                                string Mensaje = $"Se realiza el Reverso de la Devolución de IVA " +
                            $"\n por {respuestaAnulaDevolucion.montoIvaDevolver:N} \n de la factura";


                                imprimeTicketDevolcionIVA(
                                   respuestaDevIVA.codigo,
                                   Mensaje,
                                   _factura.ClienteIdentificacion,
                                   _factura.Cliente_nombre,
                                   "REVERSA_IVA");


                                DevolucionIvaModel devolucionIva = new DevolucionIvaModel();
                                devolucionIva.tipoDocumento = _factura.Documento;
                                devolucionIva.establecimiento = _factura.Establecimiento;
                                devolucionIva.puntoEmision = _factura.PtoEmision;
                                devolucionIva.numDocumento = _factura.Secuencia.ToString();
                                devolucionIva.ClaveAccesoSRI = _factura.ClaveAccesoSRI;
                                devolucionIva.cliente = _factura.ClienteIdentificacion;
                                devolucionIva.estado = "R";

                                Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindow", "ejecutaReversoDevolucionIVA", $"Ejecuta metodo  grabaDevolucionIVA");
                                _factura.grabaDevolucionIVA(devolucionIva);

                                _factura.aplicaBeneficioDevolucionIVA = false;
                                _factura.montoIvaDevolver = 0;
                                _factura.pinClteDevolucion = "";

                                _factura.Documento = "F";
                                string ClaveAccesoSRI = string.Empty;
                                
                                if (Control.Common.GlobalParameters.SRI_ACTIVAR_CLAVE_ACCESO)
                                {
                                    Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindows", "getProducto", " Regenera Clave de Acceso.");
                                    ClaveAccesoSRI = _factura.generarClaveAccesoSRI(_factura.Documento);
                                }

                                _factura.ClaveAccesoSRI = ClaveAccesoSRI;
                                
                                Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindows", "getProducto", " reverso de IVA realizado correctamente.");
                                Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindows", "getProducto", " variables fueron enceradas");
                            }
                            else
                            {
                                Task.Run(() => Control.Common.General.GetMensajeToList(656));
                            }
                        }

                        if (codMensaje == 999)
                        {
                            Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindows", "ValidacionBeneficioIVA", "Resultado de validacion de Beneficiario IVA");

                            parametros = new List<ParametrosMensajes>();
                            parametros.Add(new ParametrosMensajes()
                            {
                                codigo = "[Message]",
                                valor = respuestaDevIVA.mensaje
                            });

                            //parametros.Add(new ParametrosMensajes() { codigo = "[MENSAJE]", valor = respuestaDevIVA.mensaje });
                            Task.Run(() => Control.Common.General.GetMensajeToList(codMensaje, screenClte));
                        }
                        else {
                            Task.Run(() => Control.Common.General.GetMensajeToList(codMensaje, screenClte));
                        }
                        
                        return false;
                    }
                }

            }

            return true;

        }


        private void btnEfectivo_Click(object sender, EventArgs e)
        {

            Screen screenClte = Control.Common.General.GetScreenClte();
            Screen screenCajero = Control.Common.General.GetScreenCajero();
            List<ParametrosMensajes> parametros = new List<ParametrosMensajes>();

            try
            {
                QuitarDescuentoPromocionTarjetaBines();

                decimal totalFactura = decimal.Parse(this.lblTotal2.Text.Replace("$", ""));
                decimal valorRestante = decimal.Parse(this.lblRestante.Text.Replace("$", ""));
                decimal PagoValor = 0;
                if (this.txtPagoValor.Text != "") { PagoValor = decimal.Parse(this.txtPagoValor.Text.Replace("$", "")); }

                decimal valorIngresado = 0M;
                decimal.TryParse(txtPagoValor.Text, out valorIngresado);

                if (!decimal.TryParse(txtPagoValor.Text, out valorIngresado) || valorIngresado <= 0)
                {
                    Control.Common.General.GetMensajeToList(106); // Mensaje: Valor inválido
                    flagEjecutaPago = true;
                    EjecutaBotonPago(OrigenBoton.Pago);
                    flagProcesarDsct = false;
                    return;
                }

                if (_factura.esBeneficiarioDevolucionIVA)
                {

                    if (Control.Common.GlobalParameters.SRI_ACTIVAR_CLAVE_ACCESO)
                    {
                        _factura.ClaveAccesoSRI = _factura.generarClaveAccesoSRI(_factura.Documento);
                    }
                }

                if (!ValidacionBeneficioIVA("btnEfectivo")) { return; }


                //lblCanalVenta
                //CANALVENTA.VENTAAPPPOS
                if (_factura.EsEmpleadoLiris && _factura.PedidoOtraApp.Tipo == (byte)CANALVENTA.VENTANORMALPOS)
                {
                    revisarCambioEnTotal("TAR PORTAL", "TAR PORTAL");
                }

                // Proceso normal de pago en efectivo
                if (!EfectivoExactoButton)
                {
                    
//                    revisarCambioEnTotal("TAR PORTAL", "EFECTIVO");
                    flagEjecutaPago = true;
                    EjecutaBotonPago(OrigenBoton.Pago);
                    flagProcesarDsct = false;
                }

                // Agregar pago efectivo si hay saldo pendiente
                if (_factura != null && valorRestante > 0 && valorIngresado > 0)
                {
                    _factura.agregarPagoEfectivo(valorIngresado);
                    txtPagoValor.Clear();
                    calcularFactura();
                    agregaFormasPagoTmpFile();
                }
            }
            catch (Exception ex)
            {
                Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Error,
                    "POS.Control.Main.MainTouch.frmPinCliente", "btnEfectivo_Click",
                    $"Error al procesar pago en efectivo: {ex.Message}\n{ex.StackTrace}");

                parametros = new List<ParametrosMensajes>();
                parametros.Add(new ParametrosMensajes() { codigo = "[Message]", valor = ex.Message });


                Control.Common.General.GetMensajeToList(999, parametros, ex.StackTrace); // Mensaje genérico de error
            }
        }

        private void btnEliminarPago_Click(object sender, EventArgs e)
        {

            if (gridPagos.SelectedRows.Count > 0)
            {
                var codigo = gridPagos.SelectedRows[0].DataBoundItem as POS.Models.Pago;
                Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindow", "btnEliminarPago_Click", "Acción borrar pago solicitada por usuario sobre pago tipo: " + codigo.Descripcion + ", valor: " + codigo.Valor.ToString("N2"));
                //QuitarDescuentoPromocionTarjetaBines();
                if (codigo.Descripcion == "T. CREDITO")
                {
                    flagBorrarPago = true; //validación para que no muestre pantalla promo tarjeta bines si se va a eliminar un pago con TC.
                    btnTCredito_Click(sender, e);
                }
                else
                {
                    this._factura.borrarDescuentoFormaPago(codigo.Descripcion);

                    if (codigo.Descripcion == "TAR PORTAL")
                    {
                        ActivateDivisionEmployDiscounts(false, true);
                    }

                    if (codigo.Descripcion == "ANTCLIEN/C" && Control.Common.GlobalParameters.RECALCULAR_IVA12_X_PAGONC == true)
                    {
                        Control.Common.GlobalParameters.RECALCULAR_IVA12_X_PAGONC = false;
                        foreach (var item in _factura.Productos)
                        {
                            if (item.Iva > 0M)
                            {
                                item.calcularIVA(Control.Common.GlobalParameters.IVAGEN);
                            }
                        }
                    }

                    GridViewRowInfo selectedRow = gridPagos.SelectedRows[0];
                    //if (codigo.Descripcion.ToString().ToUpper() == "DINE ELECT" && this.FacturaActual.PedidoOtraApp.Tipo == (int)CANALVENTA.VENTAAPPPOS)
                    if (this.FacturaActual.PedidoOtraApp.Tipo == (int)CANALVENTA.VENTAAPPPOS)
                    {
                        Control.Common.General.GetMensajeToList(178);
                        //System.Windows.Forms.MessageBox.Show("Lo sentimos, no se puede eliminar la forma de pago ya que viene desde la App.", "Formas de Pago", MessageBoxButtons.OK, MessageBoxIcon.Information);
                    }
                    else
                    {
                        gridPagos.SelectedRows[0].Delete();
                        calcularFactura();
                        agregaFormasPagoTmpFile();
                    }
                }
            }
        }

        /// <summary>
        /// Verifica si es la impresora esta con un driver generico, si es asi le agrega un ENDLINE adicional.
        /// </summary>
        /// <param name="printer">Objeto PCPrint</param>
        /// <param name="s">Contenedor de texto</param>
        /// <param name="text">Text a agregar</param>
        private void addCL(DSS.Controles.Impresion.DSSPrint printer, StringBuilder s, string text)
        {
            s.AppendLine(text);
            if (printer.PrinterSettings.PrinterName.Contains("Generic"))
                s.Append("\n");
        }

