                                        // System.Windows.Forms.MessageBox.Show(this, "La tarjeta " + tarjeta.codigo + " ya se encuentra activa, registre otra tarjeta", "Tarjeta Descuento", MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
                                        return false;
