        private decimal sumardetalleGiftCard(BindingList<PagoBase> pagos)
        {
            decimal respua = 0;
            foreach (var pgif in pagos)
            {
                respua = respua + pgif.Valor;

            }

            return respua;
        }


        private void ejecutaCreditoInterno()
        {
            QuitarDescuentoPromocionTarjetaBines();
            ActivateDivisionEmployDiscounts(true);
            revisarCambioEnTotal("TAR PORTAL", "TAR PORTAL");

            decimal valorRetante = decimal.Parse(this.lblRestante.Text.Replace("$", ""));

            //MainWindow clonedMainWindow = (MainWindow)this.MemberwiseClone();
            this.Enabled = false;
            using (var basePago = new POS.Control.Pagos.BasePagos(
                             Control.Pagos.BasePagos.PagoTipo.TarjetaInterna,
                             ref _factura,
                             valorRetante))
            {
                basePago._mainWindow = this;
                basePago.StartPosition = FormStartPosition.CenterParent;
                basePago.Owner = this;

                var result = basePago.ShowDialog(this);
                _bloquearFocoEnActivacion = false;

                //this.Enabled = true;

                txtPagoValor.Clear();

                if (result == DialogResult.OK)
                {
                    if (basePago._tarjetaInterna != null)
                    {
                        _factura.TarjetaCreditoInterno = basePago._tarjetaInterna;
                        _factura.EsTarjetaCreditoInterno = true;
                    }

                    if (basePago._tarjetaInternaAdicional != null)
                    {
                        _factura.TarjetaCreditoInternoAdicional = basePago._tarjetaInternaAdicional;
                        _factura.EsTarjetaCreditoInternoAdicional = true;
                    }
                }

                if (!HasPayTipe("TAR PORTAL"))
                    ActivateDivisionEmployDiscounts(false);

                flagEjecutaPago = true;
