                        Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Error, "MainWindow", "AvanceCaja", $"monto_avance: {string.Format("{0:C2}", (monto_avance + 1))}");
                        Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Error, "MainWindow", "AvanceCaja", $"PagoTotalCheque: {string.Format("{0:C2}", (PagoTotalCheque))}");

