                                foreach (var prod in db.BG_Lst_POS_no_sub_AX.Where(x => x.establecimiento == this._factura.Establecimiento))
                                {
                                    cadena += String.Concat(prod.item_id, "\n", prod.item_nombre, "\n                 ", prod.cantidad, "           ", prod.total, "\n");

