        private Form frmAbierta;

        private void btnPrecio_Click(object sender, EventArgs e)
        {

            // Verificar si ya está abierto
            var frmAbierta = Application.OpenForms
                .OfType<Control.Main.PriceViewer>()
                .FirstOrDefault();

            if (frmAbierta != null)
            {
                frmAbierta.Activate();
                return;
            }

            // Crear nuevo formulario (sin 'using')
            var frmPriceViewer = new Control.Main.PriceViewer
            {
                cliente_actual = cliente_actual,
                FacturaActual = FacturaActual,
                _mainWindow = this
                // TopMost = true; → Evitar, puede causar problemas
            };



            // Centrar en la pantalla del cajero al mostrarse
            frmPriceViewer.Shown += (s, ev) =>
            {
                Screen targetScreen = Control.Common.General.GetScreenCajero();
                if (targetScreen == null)
                    targetScreen = Screen.PrimaryScreen;

                // Asegurarse de que el tamaño esté actualizado
                frmPriceViewer.Location = new Point(
                    targetScreen.WorkingArea.Left + (targetScreen.WorkingArea.Width - frmPriceViewer.Width) / 2,
                    targetScreen.WorkingArea.Top + (targetScreen.WorkingArea.Height - frmPriceViewer.Height) / 2
                );

                frmPriceViewer.BringToFront();
            };



            // Opcional: limpiar foco después del cierre
            frmPriceViewer.FormClosed += (s, ev) =>
            {
                this.txtCodigo.Focus();
                // Opcional: seleccionar todo para nuevo ingreso
                // this.txtCodigo.SelectAll();
            };

            // Mostrar como modal
            frmPriceViewer.ShowDialog(this);

            
        }

