        public void CargarYRecargarImagenes()
        {
            string rutaCarpetaLocal = Properties.Settings.Default.PATH_IMG;
            List<RutaImagen> listRutaImagen = new List<RutaImagen>();

            using (var db = new POSEntities()) // Asegúrate de que db esté instanciado
            {
                var WallPaper = db.core_parametro
                    .Where(x => x.identificador.Equals("WALLPAPER_" + Control.Common.GlobalParameters.EstablecimientoAxCode))
                    .FirstOrDefault();

                // Asegurar que la carpeta local exista
                if (!Directory.Exists(rutaCarpetaLocal))
                {
                    Directory.CreateDirectory(rutaCarpetaLocal);
                }

                var DetWallPaper = (from deta in db.core_parametro
                                    where deta.identificador == "DETWALLPAPER"
                                    && deta.valor == WallPaper.id.ToString()
                                    select new
                                    {
                                        Establecimiento = Control.Common.GlobalParameters.Establecimiento,
                                        EstablecimientoAxCode = Control.Common.GlobalParameters.EstablecimientoAxCode,
                                        Ruta = deta.parametro2
                                    }).ToList();

                if(DetWallPaper != null || DetWallPaper.ToList().Count > 0)
                {
                    foreach (var deta in DetWallPaper)
                    {
                        var rutaImagen = new RutaImagen
                        {
                            Establecimiento = deta.Establecimiento,
                            EstablecimientoAxCode = deta.EstablecimientoAxCode,
                            Ruta = deta.Ruta // Ruta original (servidor)
                        };

                        string nombreArchivo = Path.GetFileName(deta.Ruta);
                        string rutaLocalDestino = Path.Combine(rutaCarpetaLocal, nombreArchivo);

                        try
                        {
                            // Intentar copiar desde servidor si existe
                            if (File.Exists(deta.Ruta))
                            {
                                File.Copy(deta.Ruta, rutaLocalDestino, true); // Sobrescribir
                                rutaImagen.Ruta = rutaLocalDestino; // Actualizar a ruta local
                            }
                            else if (File.Exists(rutaLocalDestino))
                            {
                                // Si no existe en servidor, usar copia local existente
                                rutaImagen.Ruta = rutaLocalDestino;
                            }
                            else
                            {
                                // No existe en ningún lado
                                Control.Common.Logger.LogMessage(
                                    Control.Common.Enum.LogTypes.Warn,
                                    "CargarYRecargarImagenes",
                                    "ProcesarImagen",
                                    $"No se encontró el archivo: {deta.Ruta} ni en servidor ni local.",
                                    string.Empty);
                                continue; // Saltar esta imagen
                            }

                            // ✅ Cargar imagen SIN bloquear el archivo físico
                            byte[] imageData = File.ReadAllBytes(rutaImagen.Ruta);
                            using (var ms = new MemoryStream(imageData))
                            {
                                using (var original = Image.FromStream(ms))
                                {
                                    rutaImagen.imgenEstablecimiento = new Bitmap(original); // ¡Clonamos!
                                }
                            }

                            listRutaImagen.Add(rutaImagen);
                        }
                        catch (Exception ex)
                        {
                            Control.Common.Logger.LogMessage(
                                Control.Common.Enum.LogTypes.Error,
                                "CargarYRecargarImagenes",
                                "ProcesarImagen",
                                $"Error al procesar {deta.Ruta}: {ex.Message}",
                                ex.StackTrace);

                            // Opcional: agregar imagen con null o placeholder si falla
                            // rutaImagen.imgenEstablecimiento = null;
                            // listRutaImagen.Add(rutaImagen);
                        }
                    }
                }

             
            }

            // Asignar lista final
            POS.Control.Common.GlobalParameters.ListWallPapers = listRutaImagen;
        }

        private void ValidarMonedero(string identificacion)
        {
            decimal saldoPuntos = 0;
            try
            {
                using (POSEntities db = new POSEntities())
                {
                    if (db.TblPuntosCab.Any(x => x.AccountNum == identificacion && x.Estado == 1))
                    {
                        var puntoscab = db.TblPuntosCab.Where(x => x.AccountNum == identificacion && x.Estado == 1).ToList();
                        if (puntoscab != null && puntoscab.Count > 0)
                        {
                            saldoPuntos = puntoscab.Sum(x => x.Saldo);
                            if (saldoPuntos > 0)
                            {
                                _factura.SaldoPuntos = saldoPuntos * Control.WalletPoints.ClsPoints.FactorCanje;
                                btnMonedero.Visible = (_factura.EsUsoAppMovil && POS.Control.Common.GlobalParameters.MonederoConsumoActivo);
                            }
                            else
                            {
                                btnMonedero.Visible = false;
                            }
                            Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindow", "ValidarMonedero", "CI:" + identificacion + ", saldo de puntos TblPuntosCab:" + saldoPuntos.ToString());//stefany                           
                        }
                        else
                        {
                            btnMonedero.Visible = false;
                        }

                    }
                }

            }
            catch (Exception ex)
            {
                Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Error, "MainWindow", "ValidarMonedero", "A continuacion las excepciones encontradas - " + Control.Common.ExceptionHandler.GetExceptionMessages(ex), "StackTrace: " + ex.StackTrace);
            }


        }




        /// <summary>
        /// Obtiene el saldo del monedero del cliente por campaña.
        /// </summary>
        /// <param name="identificacion"></param>
        /// <param name="idCampania"></param>
        private void ValidarMonederoCampania(string identificacion)
        {
            int idCampania = 0;
            decimal saldoPuntos = 0.0M;
            Boolean _tieneCampania = true;
            using (POSEntities db = new POSEntities())
            {

                _tieneCampania = false;
                if (db.core_parametro.Any(x => x.identificador == "CAMPANIA_MONEDERO"))
                {
                    string valor = db.core_parametro.Where(x => x.identificador == "CAMPANIA_MONEDERO").FirstOrDefault().valor;
                    if (!string.IsNullOrEmpty(valor))
                    {

                        _tieneCampania = false;
                        if (valor != "0")
                        {
                            idCampania = Convert.ToInt32(valor);
                            _tieneCampania = true;
                        }
                    }
                }


                if (_tieneCampania)
                {

                    if (identificacion == "" || identificacion == "9999999999999")
                    {
                        btnMonedero.Visible = false;
                        btnCuponApp.Visible = false;
                    }
                    else
                    {
                        string cadenaCon = "";

                        if (Control.Common.GlobalParameters.ConServerPuntos != "")
                        {
                            cadenaCon = Control.Common.GlobalParameters.ConServerPuntos;
                        }
                        else
                        {
                            Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindow", "ValidarMonederoCampania", "No hay parametro 'CON_SERVER_PUNTOS' para este local o esta vacío ");
                            MessageBox.Show(this, "La Billetera Electrónica esta fuera de línea y no se puede utilizar (No hay parametro 'CON_SERVER_PUNTOS' para este local), intente más tarde", "Mensaje", MessageBoxButtons.OK, MessageBoxIcon.Error);
                        }

                        if (string.IsNullOrEmpty(cadenaCon))
                        {

                            Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindow", "ValidarMonederoCampania", $"cadenaCon: {cadenaCon}");
                            return;
                        }

                        string query = string.Empty;

                        try
                        {
                            query = string.Empty;
                            query = string.Concat(query, $"declare @AccountNum as varchar(20) = '{identificacion}' ", Environment.NewLine);
                            query = string.Concat(query, $"declare @respuesta as decimal(10,2) ", Environment.NewLine);
                            query = string.Concat(query, $" exec [PtsCliente].[spValidarHistoricoPuntosGen] ", Environment.NewLine);
                            query = string.Concat(query, $" @AccountNum ", Environment.NewLine);
                            query = string.Concat(query, $", @respuesta out ", Environment.NewLine);
                            query = string.Concat(query, $"Select @respuesta respuesta", Environment.NewLine);

                            Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindow", "ValidarMonederoCampania", $"query: {query}");
                            //Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindow", "ValidarMonederoCampania", $"Inicia: {DateTime.Now.ToString("dd/MM/yyyy HH:MM:SS")  }");

                            DataSet dtsConsulta = Control.Common.General.GetDataSet(query, cadenaCon);
                            if (dtsConsulta.Tables.Count > 0)
                            {
                                if (dtsConsulta.Tables[0].Rows.Count > 0)
                                {
                                    string saldoPuntos_ = string.Empty;
                                    saldoPuntos_ = dtsConsulta.Tables[0].Rows[0]["respuesta"].ToString();
                                    decimal.TryParse(saldoPuntos_, out saldoPuntos);
                                    Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindow", "ValidarMonederoCampania", $"saldoPuntos: {saldoPuntos}");

                                    if (saldoPuntos > 0.0M)
                                    {
                                        _factura.SaldoPuntos = Math.Round(saldoPuntos * Control.WalletPoints.ClsPoints.FactorCanje, 2);
                                        btnMonedero.Visible = (_factura.EsUsoAppMovil && POS.Control.Common.GlobalParameters.MonederoConsumoActivo);

                                        Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindow", "ValidarMonederoCampania", $"_factura.SaldoPuntos: {_factura.SaldoPuntos}");
                                    }
                                    else
                                    {
                                        btnMonedero.Visible = false;
                                    }
                                }
                            }
                        }
                        catch (Exception ex)
                        {
                            _factura.EsUsoAppMovil = false;
                            MessageBox.Show(this, "La Billetera Electrónica esta fuera de línea y no se puede utilizar, intente más tarde", "Mensaje", MessageBoxButtons.OK, MessageBoxIcon.Error);
                            btnMonedero.Visible = false;
                            Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Error, "MainWindow", "ValidarMonederoCampania", "Billetera Electrónica esta fuera de línea, a continuacion las excepciones encontradas - " + Control.Common.ExceptionHandler.GetExceptionMessages(ex), "StackTrace: " + ex.StackTrace);
                        }

                        


                    }
                }
                else
                {
                    ValidarMonedero(identificacion);
                }

            }
        }


