        //jchid eliminar todo los archivos temporales en para el cierre de Caja 
        public void LimpiezaCompletaCierreCaja()
        {
            Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindow", "LimpiezaCompletaCierreCaja", "Iniciando limpieza completa para cierre de caja");

            if (NoGrabaTMP == "FALSE" && !Es2X_CONSULTA_POS)
            {
                try
                {
                    string carpetaArchivos = null;
                    string[] tiposParaRuta = { "Cab.txt", "Det.txt", "Pag.txt" };

                    // Intentar obtener la carpeta usando cualquiera de los tipos
                    foreach (string tipoRuta in tiposParaRuta)
                    {
                        try
                        {
                            string rutaEjemplo = ConectividadSharedTmpFile(POS.Control.Common.GlobalParameters.DBIdCaja, Program.ID_Caja_POS, tipoRuta);

                            if (!string.IsNullOrEmpty(rutaEjemplo))
                            {
                                carpetaArchivos = Path.GetDirectoryName(rutaEjemplo);
                                Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindow", "LimpiezaCompletaCierreCaja", $"Carpeta obtenida usando {tipoRuta}: {carpetaArchivos}");
                                break; // Salir del bucle al encontrar una ruta válida
                            }
                        }
                        catch (Exception exRuta)
                        {
                            Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Warning, "MainWindow", "LimpiezaCompletaCierreCaja", $"Error obteniendo ruta con {tipoRuta}: {exRuta.Message}");
                        }
                    }

                    // Verificar que se obtuvo una carpeta válida
                    if (string.IsNullOrEmpty(carpetaArchivos))
                    {
                        Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Error, "MainWindow", "LimpiezaCompletaCierreCaja", "No se pudo obtener ninguna ruta válida para archivos temporales");
                        return;
                    }

                    if (!Directory.Exists(carpetaArchivos))
                    {
                        Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Warning, "MainWindow", "LimpiezaCompletaCierreCaja", $"Directorio no existe: {carpetaArchivos}");
                        return;
                    }

                    // Continuar con la eliminación...
                    int totalEliminados = 0;
                    string[] tiposArchivo = { "Cab.txt", "Det.txt", "Pag.txt" };

                    foreach (string tipo in tiposArchivo)
                    {
                        try
                        {
                            string[] archivosEncontrados = Directory.GetFiles(carpetaArchivos, "*" + tipo);
                            Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindow", "LimpiezaCompletaCierreCaja", $"Archivos {tipo} encontrados: {archivosEncontrados.Length}");

                            foreach (string archivo in archivosEncontrados)
                            {
                                try
                                {
                                    if (File.Exists(archivo))
                                    {
                                        File.Delete(archivo);
                                        Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindow", "LimpiezaCompletaCierreCaja", $"Eliminado: {Path.GetFileName(archivo)}");
                                        totalEliminados++;
                                    }
                                }
                                catch (Exception exDelete)
                                {
                                    Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Warning, "MainWindow", "LimpiezaCompletaCierreCaja", $"Error eliminando {Path.GetFileName(archivo)}: {exDelete.Message}");
                                }
                            }
                        }
                        catch (Exception exTipo)
                        {
                            Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Warning, "MainWindow", "LimpiezaCompletaCierreCaja", $"Error buscando archivos {tipo}: {exTipo.Message}");
                        }
                    }

                    tieneProductosTmp = false;
                    Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "MainWindow", "LimpiezaCompletaCierreCaja", $"Limpieza completa finalizada. Archivos eliminados: {totalEliminados}");

                }
                catch (Exception ex)
                {
                    Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Error, "MainWindow", "LimpiezaCompletaCierreCaja", "Error general: " + Control.Common.ExceptionHandler.GetExceptionMessages(ex), "StackTrace: " + ex.StackTrace);
                }
            }
        }

        private string ConectividadSharedTmpFile(string shared, string idPOS, string tipo)
        {
            bool recursoCompartidoDisponible = true;
            string txtFile = string.Empty;
            try
            {
                //bool recursoCompartidoDisponible = QuickBestGuessAboutAccessibilityOfNetworkPath(shared);                
                recursoCompartidoDisponible = Directory.Exists(@shared);
                if (recursoCompartidoDisponible)
                {
                    return shared + idPOS + tipo;
                }
                else
                {
                    POS.Control.Common.GlobalParameters.DBIdCaja = POS.Control.Common.GlobalParameters.DBIdCajaLocal;
                    return POS.Control.Common.GlobalParameters.DBIdCajaLocal + idPOS + tipo;
                }

            }
            catch (Exception)
            {
                //Si existe error desconocido o no tratado, entonces que obtenga la ruta Local.
                POS.Control.Common.GlobalParameters.DBIdCaja = POS.Control.Common.GlobalParameters.DBIdCajaLocal;
                return POS.Control.Common.GlobalParameters.DBIdCajaLocal + idPOS + tipo;
            }
        }


        private string ObtenerRutaLocalTmpFile(string idPOS, string tipo)
        {
   
            POS.Control.Common.GlobalParameters.DBIdCaja = POS.Control.Common.GlobalParameters.DBIdCajaLocal;
            return POS.Control.Common.GlobalParameters.DBIdCajaLocal + idPOS + tipo;
        }

        private bool QuickBestGuessAboutAccessibilityOfNetworkPath(string path)
        {
            if (string.IsNullOrEmpty(path)) return false;
            string pathRoot = Path.GetPathRoot(path);
            if (string.IsNullOrEmpty(pathRoot)) return false;
            ProcessStartInfo pinfo = new ProcessStartInfo("net", "use");
            pinfo.CreateNoWindow = true;
            pinfo.RedirectStandardOutput = true;
            pinfo.UseShellExecute = false;
            string output;
            using (Process p = Process.Start(pinfo))
            {
                output = p.StandardOutput.ReadToEnd();
            }
            foreach (string line in output.Split('\n'))
            {
                if (line.Contains(pathRoot) && line.Contains("OK"))
                {
                    return true; // shareIsProbablyConnected
                }
            }
            return false;
        }

