        private void ShowPinForm(Form owner, Screen targetScreen, Factura factura,
            out string pinIngresado, out decimal montoIvaDevolver,
            out int codigoMensaje, out string mensajeRespuesta, out string claveAccesoSRI)
        {
            pinIngresado = null;
            montoIvaDevolver = 0;
            codigoMensaje = 0;
            mensajeRespuesta = string.Empty;
            claveAccesoSRI = string.Empty;

            try
            {
                using (var pinForm = new POS.Control.Main.MainTouch.frmPinCliente())
                {
                    pinForm.tipoComprobante = "01";
                    pinForm._factura = factura;

                    // Centrar en la pantalla objetivo
                    int x = targetScreen.WorkingArea.Left + (targetScreen.WorkingArea.Width - pinForm.Width) / 2;
                    int y = targetScreen.WorkingArea.Top + (targetScreen.WorkingArea.Height - pinForm.Height) / 2;
                    pinForm.Location = new Point(x, y);

                    // Mostrar diálogo modal con el formulario principal como propietario
                    DialogResult result = pinForm.ShowDialog(owner);

                    Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "frmMainTouchClte", "ShowPinForm", "Retorna respuesta Devolucion IVA ");
                    if (result == DialogResult.OK)
                    {
                        Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "frmMainTouchClte", "ShowPinForm", $"Respuesta correcta CodMensaje {pinForm.CodigoMensaje}" +
                            $"Mensaje: {pinForm.Mensaje};  "
                            );


                        pinIngresado = pinForm.Pin;
                        montoIvaDevolver = pinForm.montoIvaDevolver;
                        codigoMensaje = int.Parse(pinForm.CodigoMensaje);
                        mensajeRespuesta = pinForm.Mensaje;
                        claveAccesoSRI = pinForm.ClaveAccesoSRI;

           
                        DevolucionIvaModel devolucionIva = new DevolucionIvaModel();
                        devolucionIva.tipoDocumento = _factura.Documento;
                        devolucionIva.establecimiento = _factura.Establecimiento;
                        devolucionIva.puntoEmision = _factura.PtoEmision;
                        devolucionIva.numDocumento = _factura.Secuencia.ToString();
                        devolucionIva.ClaveAccesoSRI = pinForm.ClaveAccesoSRI;
                        devolucionIva.montoIvaDevolver = pinForm.montoIvaDevolver;    //_factura.getIVA();  cambiar por el valor a delvolver jchid 
                        devolucionIva.cliente = _factura.ClienteIdentificacion;
                        devolucionIva.estado = "I";

                        Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Info, "frmMainTouchClte", "ShowPinForm", $"Ejecuta metodo  grabaDevolucionIVA");
                        _factura.grabaDevolucionIVA(devolucionIva);




                    }
                    else if (result == DialogResult.Cancel)
                    {
                        codigoMensaje = int.Parse(pinForm.CodigoMensaje);
                        mensajeRespuesta = pinForm.Mensaje;
                    }
                }
            }
            catch (Exception ex)
            {
                // Registrar el error
                Control.Common.Logger.LogMessage(
                    Control.Common.Enum.LogTypes.Error,
                    "frmMainTouchClte",
                    "ShowPinForm",
                    ex.Message,
                    "StackTrace: " + ex.StackTrace);

                MsgBoxCtrl.MessageBoxResult result = new MsgBoxCtrl().ShowMessage(
                    MsgBoxCtrl.MessageType.Error,
                    "Ocurrió un error al mostrar el formulario de PIN.",
                    "Error");

                codigoMensaje = 1002;
                mensajeRespuesta = "Error al mostrar el formulario de PIN.";
            }
        }


        private RespuestaDevlucion EjecutaDevolucionIVA()
        {
            var respuesta = new RespuestaDevlucion();
            string pinIngresado = string.Empty;
            decimal montoIvaDevolver = 0;
            int codigoMensaje = 0;
            string claveAccesoSRI = string.Empty;
            string mensajeRespuesta = string.Empty;

            try
            {
                Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Error, "MainWindow", "EjecutaDevolucionIVA", "Inicia proceso de devolución de IVA");

                 
                var mainForm = Application.OpenForms.Cast<Form>().FirstOrDefault(f => f is frmMainTouchClte) as frmMainTouchClte;


                if (mainForm != null)
                {
                    // Obtener la pantalla donde está frmMainTouchClte
                    Screen targetScreen = Control.Common.General.GetScreenClte() ?? Screen.PrimaryScreen;

                    // Asegurarse de que estamos en el hilo de la UI
                    if (mainForm.InvokeRequired)
                    {
                        mainForm.Invoke(new MethodInvoker(delegate
                        {
                            ShowPinForm(mainForm, targetScreen, _factura, out pinIngresado, out montoIvaDevolver, out codigoMensaje, out mensajeRespuesta, out claveAccesoSRI);
                        }));
                    }
                    else
                    {
                        ShowPinForm(mainForm, targetScreen, _factura, out pinIngresado, out montoIvaDevolver, out codigoMensaje, out mensajeRespuesta, out claveAccesoSRI);
                    }
                }
                else
                {

                    // Si no hay frmMainTouchClte, usar pantalla principal
                    Screen targetScreen = Screen.PrimaryScreen;

                    // Crear un form temporal oculto para usar como "owner" si es necesario
                    using (Form dummy = new Form())
                    {
                        dummy.StartPosition = FormStartPosition.Manual;
                        dummy.Location = new Point(targetScreen.WorkingArea.Left + 100, targetScreen.WorkingArea.Top + 100);
                        dummy.Size = new Size(1, 1);
                        dummy.ShowInTaskbar = false;
                        dummy.Opacity = 0;
                        dummy.Show();

                        ShowPinForm(dummy, targetScreen, _factura, out pinIngresado, out montoIvaDevolver, out codigoMensaje, out mensajeRespuesta, out claveAccesoSRI);
                    }


                    //codigoMensaje = 999;
                    //mensajeRespuesta = "Ventana principal no encontrada.";
                }
                
                
            }
            catch (Exception ex)
            {
                mensajeRespuesta = "Error: " + ex.Message;
                codigoMensaje = -3;

                Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Error, "MainWindow", "EjecutaDevolucionIVA", ex.ToString());
            }
            finally
            {
                _bloquearFocoEnActivacion = false;
            }

            respuesta.codigo = codigoMensaje.ToString();
            respuesta.mensaje = mensajeRespuesta;
            respuesta.montoIvaDevolver = montoIvaDevolver;
            respuesta.claveAccesoComprobante = claveAccesoSRI;
            respuesta.pinClteDevolucion = pinIngresado;

            return respuesta;
        }


        private bool validaDeovlucionIVA(Factura factura, Screen pantallaCajero)
        {

            string mensajeError = string.Empty;
            // Si hay más de un tipo de pago...
            if (factura.Pagos != null && factura.Pagos.Count > 1)
            {
                // Busca cualquier pago que no sea efectivo
                var pagosNoEfectivo = factura.Pagos
                    .Where(p => !string.Equals(p.Descripcion.Trim(), "EFECTIVO", StringComparison.OrdinalIgnoreCase))
                    .ToList();

                if (pagosNoEfectivo.Count > 0)
                {
                    // Mensaje al cajero
                    Control.Common.General.GetMensajeToList(648, pantallaCajero);

                    mensajeError = "Solo se puede aplicar para pagos completos en efectivo";
                    Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Error, "MainWindow", "validaDeovlucionIVA", mensajeError);

                    return false;
                }
            }

            // Si hay un solo pago, validar que sea efectivo
            else if (factura.Pagos != null && factura.Pagos.Count == 1)
            {
                var primerPago = factura.Pagos.FirstOrDefault();

                if (primerPago == null ||
                   !string.Equals(primerPago.Descripcion.Trim(), "EFECTIVO", StringComparison.OrdinalIgnoreCase))
                {
                    Control.Common.General.GetMensajeToList(648, pantallaCajero);

                    mensajeError = "El beneficio solo aplica a pagos realizados en efectivo.";
                    Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Error, "MainWindow", "validaDeovlucionIVA", mensajeError);
                    return false;
                }
            }

            // Si no hay pagos registrados
            else
            {
                Control.Common.General.GetMensajeToList(106, pantallaCajero);

                mensajeError = "No se han registrado pagos para esta transacción.";
                Control.Common.Logger.LogMessage(Control.Common.Enum.LogTypes.Error, "MainWindow", "validaDeovlucionIVA", mensajeError);
                return false;
            }

            mensajeError = string.Empty;
            return true; // Es válido
        }


