                return;

            lock (lockPrinter)
            {
                Control.Common.Printer.Imprimir(texto, tipo, ptosInterlineado);
            }
        }





        public async void EjecutarCargaArchivosTmpAsync()
        {
            DatosFacturaCargados datosCargados = null;
            string codigocliente = string.Empty;
            if (UCLoading2 == null)
            {
                UCLoading2 = new UC_Loading();
            }
            // Asegurarse de que esté en el formulario
            if (!this.Controls.Contains(UCLoading2))
                this.Controls.Add(UCLoading2);
            // Configurar el control de carga
            UCLoading2.Visible = true;
            UCLoading2.lblSeguimientoEvent.Text = "Recuperación de información";
            UCLoading2.Top = 20;
            UCLoading2.Left = (Screen.PrimaryScreen.WorkingArea.Width / 2) - (UCLoading2.Width / 2);
            UCLoading2.BringToFront();
            // Forzar actualización de la UI para que se muestre antes de la operación larga
            //UCLoading2.Update();
            // Variable para capturar si hubo error en CargaFacturaTmpFile
            bool huboError = false;
            try
            {
                // Ejecutar la operación larga en un hilo en segundo plano
                datosCargados = await Task.Run(() => CargaFacturaTmpFile());
            }
            catch (Exception ex)
            {
                huboError = true;
                Control.Common.Logger.LogMessage(
                    Control.Common.Enum.LogTypes.Error,
                    "MainWindow",
                    "EjecutarCargaArchivosTmp",
                    "Error en CargaFacturaTmpFile: " + ex.Message,
                    "StackTrace: " + ex.StackTrace);
            }
            finally
            {
                // Asegurarse de ocultar el loading
                if (this.Controls.Contains(UCLoading2))
                {
                    UCLoading2.Visible = false;
                    this.Controls.Remove(UCLoading2);
                }

            }
            // Continuar con la lógica POST-CARGA (esto ya está en el hilo de UI)
            if (!huboError && !Entrocatch)
            {
                // Actualizar la UI con los datos leídos del archivo.
                try
                {
                    // Cargar cabecera
                    if (!string.IsNullOrEmpty(datosCargados.CodigoCliente))
                    {
                        txtCedula.Text = datosCargados.CodigoCliente;
                        _factura.EsEmpleadoLiris = datosCargados.EsEmpleadoLiris;
                        _factura.EsClienteApp = datosCargados.EsClienteApp;
                        _factura.codigoclienteAPP = datosCargados.CodigoClienteApp;
                        _factura.EsTarjetaCreditoInterno = datosCargados.EsTarjetaCreditoInterno;
                        _factura.EsTarjetaCreditoInternoAdicional = datosCargados.EsTarjetaCreditoInternoAdicional;
                    }

                    // Cargar productos
                    foreach (var producto in datosCargados.Productos)
                    {
                        _factura.Productos.Add(producto);
                    }

                    // Cargar formas de pago
                    //foreach (var pago in datosCargados.Pagos)
                    //{
                    //    // Asumiendo un método de agregar pago en la factura
                    //    _factura.AgregarPago(pago); 
                    //}

                    // Lógica de cálculo y refresco de la UI
                    if (!String.IsNullOrEmpty(txtCedula.Text))
                    {
                        validaClienteSp(txtCedula.Text);
                    }

                    PromosPrecioPorCombinacion();
                    PromosDsctoPorSuplemento();
                    promoiva(_factura, null);
                    calcularFactura();
                    RefrescarGridItems();

                    // Lógica de alerta si existen productos temporales
                    if (Control.Common.GlobalParameters.UserObj != null)
                    {
                        if (_factura.Productos.Count > 0)
                        {
                            tieneProductosTmp = true;
                            if (!Control.Common.GlobalParameters.UserObj.isSuperUser)
                            {
                                var frm = new Control.Main.TempInvoiceAlert();
                                frm.ShowDialog();
                            }
                        }
                    }
                }
                catch (Exception ex)
                {
                    Control.Common.Logger.LogMessage(
                        Control.Common.Enum.LogTypes.Error,
                        "MainWindow",
                        "EjecutarCargaArchivosTmpAsync",
                        "Error al procesar y actualizar UI: " + ex.Message,
                        "StackTrace: " + ex.StackTrace);
                }
                //if (this.Controls.Contains(UCLoading2))
                //{
                //    UCLoading2.Visible = false;
                //    this.Controls.Remove(UCLoading2);
                //}
                //if (Control.Common.GlobalParameters.UserObj == null)
                //{
                //    Control.Common.Logger.LogMessage(
                //        Control.Common.Enum.LogTypes.Info,
                //        "MainWindow",
                //        "CargaFacturaTmpFile",
                //        "Se detectaron items temporales pero no se pudo levantar la pantalla para la aceptación del cajero porque el objeto de usuario estaba nulo");
                //}
